"""Hand-authored, bilingual late-stage quant research lessons."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
B = lambda en, vi: {"en": en, "vi": vi}

def S(title, theory, example, visual, agenda, exercise):
    return {"title": title, "theory": theory, "workedExample": example,
            "visual": visual, "agenda": agenda, "exercises": [exercise],
            "deliverable": B("A dated note showing the derivation, exact inputs, checked result, and one limitation.",
                             "Ghi chú có ngày gồm phép suy luận, đầu vào chính xác, kết quả đã kiểm và một giới hạn.")}

def X(id, prompt, hint, answer):
    return {"id": id, "prompt": prompt, "hint": hint, "answer": answer}

def M(week,title,foundations,objectives,sessions,diagram):
    return {"week":week,"title":title,
      "prerequisites":B("Comfort with vectors, conditional probability, derivatives, and Python/C++ arrays. Every symbol needed today is defined in the lesson.",
        "Có thể làm việc với vector, xác suất có điều kiện, đạo hàm và mảng Python/C++. Bài học định nghĩa mọi ký hiệu cần dùng."),
      "objectives":objectives,"foundations":foundations,"diagram":diagram,
      "sessions":sessions,"references":[]}

W71 = M(71,
 B("Week 71: Online learning, regret, forgetting, and drift","Tuần 71: Học trực tuyến, regret, quên và dịch chuyển"),
 B("An online learner issues a forecast from information available before an outcome, observes the outcome later, and only then updates. For squared loss, prediction ŷ_t and outcome y_t incur ℓ_t=(ŷ_t−y_t)². Cumulative loss is L_T=Σ_{t=1}^Tℓ_t. Regret is L_T minus the loss of the best comparator in a stated class; it is a relative sequence measure, not a return. Exponentially weighted least squares discounts old data with 0<ρ<1: A_t=ρA_{t−1}+x_tx_tᵀ and b_t=ρb_{t−1}+x_ty_t; a ridge estimate is w_t=(A_t+λI)⁻¹b_t. Shorter memory can respond faster to a shift but gives old noise less averaging. Chronological evaluation must preserve the order in which forecasts and labels become available.",
   "Người học trực tuyến phát dự báo bằng thông tin có trước kết quả, quan sát kết quả sau đó rồi mới cập nhật. Với bình phương sai số, dự báo ŷ_t và kết quả y_t có tổn thất ℓ_t=(ŷ_t−y_t)². Tổn thất tích lũy là L_T=Σ_{t=1}^Tℓ_t. Regret bằng L_T trừ tổn thất của đối chứng tốt nhất trong một lớp đã nêu; đây là thước đo tương đối theo chuỗi, không phải lợi nhuận. Bình phương tối thiểu có trọng số mũ giảm trọng số dữ liệu cũ bằng 0<ρ<1: A_t=ρA_{t−1}+x_tx_tᵀ và b_t=ρb_{t−1}+x_ty_t; nghiệm có ridge là w_t=(A_t+λI)⁻¹b_t. Bộ nhớ ngắn có thể phản ứng với dịch chuyển nhanh hơn nhưng trung bình hóa nhiễu cũ kém hơn. Đánh giá theo thời gian phải giữ thứ tự dự báo và lúc nhãn xuất hiện."),
 [B("Separate a forecast from its later update.","Tách dự báo khỏi bước cập nhật sau đó."),
  B("Calculate regret against an explicit comparator class.","Tính regret so với lớp đối chứng được nêu rõ."),
  B("Derive and compute a discounted least-squares update.","Suy ra và tính bước bình phương tối thiểu giảm trọng số."),
  B("Measure adaptation after a controlled change.","Đo thích nghi sau thay đổi có kiểm soát."),
  B("Evaluate forecasts in chronological information order.","Đánh giá dự báo theo thứ tự thông tin thời gian.")],
 [
 S(B("71.1 — Predict first, reveal later","71.1 — Dự báo trước, mở kết quả sau"),
   B("At origin t, the predictor f_t must be a function of the information set F_{t−1}; the target y_t is not inside that set yet. This is the prequential order: issue ŷ_t=f_t(x_t), record it, reveal y_t, compute loss, then update f_{t+1}. For squared loss, a large miss is penalized quadratically, so units and outliers matter. Keeping a forecast log before revealing labels prevents accidental hindsight. The loss is a property of a forecast/outcome pair; it does not by itself say the model is profitable or useful.",
   "Tại mốc t, bộ dự báo f_t phải là hàm của tập thông tin F_{t−1}; mục tiêu y_t chưa thuộc tập ấy. Trình tự prequential là: phát ŷ_t=f_t(x_t), ghi lại, mở y_t, tính tổn thất rồi cập nhật thành f_{t+1}. Với bình phương sai số, một lần trượt lớn bị phạt theo bình phương nên đơn vị và ngoại lệ rất quan trọng. Ghi dự báo trước khi mở nhãn giúp tránh vô tình dùng thông tin nhìn lại. Tổn thất thuộc về một cặp dự báo/kết quả; riêng nó không nói mô hình có sinh lời hay hữu ích không."),
   B("Three one-step forecasts are [1.5, 3, 5] and the later observed targets are [2, 4, 4]. Their squared errors are (1.5−2)²=0.25, (3−4)²=1, and (5−4)²=1, so the three-step cumulative loss is 2.25. The third forecast was recorded as 5 before target 4 was revealed; it is not revised after seeing the miss. The average squared loss is 2.25/3=0.75 target-units squared.",
   "Ba dự báo một bước là [1.5, 3, 5], các mục tiêu được mở sau đó là [2, 4, 4]. Sai số bình phương lần lượt là (1.5−2)²=0.25, (3−4)²=1 và (5−4)²=1, nên tổn thất tích lũy ba bước là 2.25. Dự báo thứ ba được ghi là 5 trước khi mở mục tiêu 4; không sửa lại dự báo sau khi đã thấy sai số. Sai số bình phương trung bình là 2.25/3=0.75 bình phương đơn vị mục tiêu."),
   {"kind":"xy","title":B("Forecasts issued before outcomes","Dự báo phát trước kết quả"),"caption":B("The exact three pairs are forecast [1.5,3,5] and observed [2,4,4] at origins 1,2,3. Lines connect time-ordered values; they do not show a fitted trend.","Ba cặp chính xác là dự báo [1.5,3,5] và quan sát [2,4,4] tại mốc 1,2,3. Đường nối giá trị theo thời gian, không biểu diễn xu hướng khớp."),"xLabel":B("Decision origin t","Mốc quyết định t"),"yLabel":B("Target units","Đơn vị mục tiêu"),"series":[{"name":B("Forecast, logged first","Dự báo, ghi trước"),"points":[[1,1.5],[2,3],[3,5]],"mode":"line"},{"name":B("Observed later","Quan sát sau đó"),"points":[[1,2],[2,4],[3,4]],"mode":"line"}]},
   [B("60 min — Write the prediction/reveal/update sequence for t=1,2,3 and mark exactly when each y_t becomes available.","60 phút — Viết thứ tự dự báo/mở kết quả/cập nhật cho t=1,2,3 và đánh dấu lúc từng y_t xuất hiện."),B("60 min — Recompute all three squared errors and their mean from [1.5,3,5] versus [2,4,4]; explain why the third forecast cannot be edited afterward.","60 phút — Tính lại ba sai số bình phương và trung bình từ [1.5,3,5] so với [2,4,4]; giải thích vì sao không được sửa dự báo thứ ba sau đó."),B("60 min — Implement a forecast log with columns origin, information cutoff, forecast, reveal time, target, and loss; assert cumulative loss=2.25.","60 phút — Viết nhật ký dự báo gồm mốc, thời điểm cắt thông tin, dự báo, lúc mở, mục tiêu và tổn thất; kiểm tra tổng bằng 2.25."),B("60 min — Change only forecast 3 from 5 to 4 before revealing its target, recompute the loss, and state why this is a new forecast policy rather than a correction to the old record.","60 phút — Đổi dự báo 3 từ 5 thành 4 trước khi mở mục tiêu, tính lại tổn thất và nêu vì sao đây là chính sách dự báo mới chứ không phải sửa nhật ký cũ.")],
   X("w71-d1-prequential",B("Forecasts [2,1,4] are issued before targets [3,3,2]. Compute each squared loss, cumulative loss, and mean loss. Which row would be invalid to revise after its target is known?","Dự báo [2,1,4] được phát trước các mục tiêu [3,3,2]. Tính từng sai số bình phương, tổng và trung bình. Dòng nào không được sửa sau khi đã biết mục tiêu?"),B("For each origin use (forecast−target)², then sum the three values. The recorded forecast is frozen once the target is revealed.","Ở mỗi mốc dùng (dự báo−mục tiêu)² rồi cộng ba giá trị. Dự báo đã ghi được giữ nguyên sau khi mở mục tiêu."),B("Losses are (2−3)²=1, (1−3)²=4, and (4−2)²=4. Cumulative loss=9 and mean=3. All three forecasts are immutable records after their corresponding target is revealed; a later model change creates a new forecast, not a replacement.","Tổn thất là (2−3)²=1, (1−3)²=4 và (4−2)²=4. Tổng bằng 9, trung bình bằng 3. Cả ba dự báo đều là bản ghi bất biến sau khi mở mục tiêu tương ứng; đổi mô hình về sau tạo dự báo mới chứ không thay thế bản cũ."))),
 S(B("71.2 — Regret needs a comparator","71.2 — Regret cần đối chứng"),
   B("For a fixed horizon T, cumulative loss of learner A is L_T(A)=Σℓ_t(A). Given a comparator set C, regret is R_T=L_T(A)−min_{c∈C}L_T(c). State C before inspecting results: it might be a set of constant forecasts or a set of fixed parameter vectors. Changing the comparator after seeing which one wins changes the question. Regret can be negative on a finite sample if the learner beats every comparator; it is not a guaranteed nonnegative profit metric. Comparisons require the same outcomes, forecast origins, loss function, and eligibility rules.",
   "Với chân trời cố định T, tổn thất tích lũy của người học A là L_T(A)=Σℓ_t(A). Với tập đối chứng C, regret là R_T=L_T(A)−min_{c∈C}L_T(c). Hãy nêu C trước khi xem kết quả: đó có thể là các dự báo hằng hoặc vector tham số cố định. Đổi đối chứng sau khi biết ai thắng sẽ đổi câu hỏi. Trên mẫu hữu hạn, regret có thể âm nếu người học thắng mọi đối chứng; đây không phải thước đo lợi nhuận luôn không âm. So sánh cần cùng kết quả, mốc dự báo, hàm mất mát và quy tắc đủ điều kiện."),
   B("The learner has losses [1,4,1,4], total 10. Before evaluation, define C as two constant rules with loss sequences c₁=[2,2,2,2] and c₂=[1,2,4,2]. Their totals are 8 and 9, so min_{c∈C}L_T(c)=8 and regret=10−8=2. The comparator is c₁ because its total is lower, not because it has been selected after searching an unlimited set. All three vectors refer to the same four outcomes and squared-loss units.",
   "Người học có chuỗi tổn thất [1,4,1,4], tổng 10. Trước đánh giá, định nghĩa C gồm hai quy tắc hằng với chuỗi c₁=[2,2,2,2] và c₂=[1,2,4,2]. Tổng lần lượt là 8 và 9, nên min_{c∈C}L_T(c)=8 và regret=10−8=2. Đối chứng là c₁ vì tổng thấp hơn, không phải vì được chọn sau khi tìm trong tập vô hạn. Cả ba vector dùng chung bốn kết quả và đơn vị bình phương sai số."),
   {"kind":"bars","title":B("Cumulative loss and comparator regret","Tổn thất tích lũy và regret"),"caption":B("Exact four-origin losses: learner 10, comparator c1 8, comparator c2 9; the declared comparator set is {c1,c2}, so regret=10−min(8,9)=2.","Tổn thất chính xác bốn mốc: người học 10, đối chứng c1 là 8, c2 là 9; tập đối chứng đã nêu là {c1,c2}, nên regret=10−min(8,9)=2."),"xLabel":B("Method or quantity","Phương pháp hoặc đại lượng"),"yLabel":B("Cumulative squared loss","Tổn thất bình phương tích lũy"),"values":[{"label":B("Learner","Người học"),"value":10},{"label":B("Comparator c1","Đối chứng c1"),"value":8},{"label":B("Comparator c2","Đối chứng c2"),"value":9},{"label":B("Regret","Regret"),"value":2}]},
   [B("60 min — Copy the three supplied loss vectors and verify each total without changing any origin.","60 phút — Chép ba vector tổn thất đã cho và kiểm tra tổng từng vector, không đổi mốc nào."),B("60 min — Write the comparator set C in words and symbols before calculating min_c L(c); explain why an unlimited hindsight-selected comparator would change the benchmark.","60 phút — Viết tập đối chứng C bằng lời và ký hiệu trước khi tính min_c L(c); giải thích vì sao đối chứng chọn bằng hindsight không giới hạn sẽ đổi chuẩn."),B("60 min — Implement a regret function that accepts one learner vector and an explicit list of comparator vectors; reject unequal lengths.","60 phút — Cài hàm regret nhận một vector người học và danh sách vector đối chứng tường minh; từ chối độ dài khác nhau."),B("60 min — Add a case where the learner beats both comparators, report negative finite-sample regret, and explain why that still is not a profit claim.","60 phút — Thêm trường hợp người học thắng cả hai đối chứng, báo regret âm trên mẫu hữu hạn và giải thích vì sao đó vẫn không phải tuyên bố lợi nhuận.")],
   X("w71-d2-regret",B("Learner losses are [3,1,2]. The predeclared comparators have losses a=[2,2,2] and b=[4,1,1]. Compute cumulative losses, the best comparator in C={a,b}, and regret.","Tổn thất người học là [3,1,2]. Hai đối chứng định trước có a=[2,2,2] và b=[4,1,1]. Tính tổng, đối chứng tốt nhất trong C={a,b} và regret."),B("Sum each vector first. Regret subtracts the smaller comparator total from the learner total.","Cộng từng vector trước. Regret lấy tổng người học trừ tổng nhỏ hơn trong hai đối chứng."),B("Learner total=3+1+2=6. Comparator a totals 6; b totals 4+1+1=6. Thus min_C=6 and regret=6−6=0. The result is tied against this two-rule set only; adding another comparator or changing the loss would define a different comparison.","Tổng người học=3+1+2=6. Đối chứng a có tổng 6; b cũng 4+1+1=6. Vậy min_C=6 và regret=6−6=0. Kết quả hòa trong đúng tập hai quy tắc này; thêm đối chứng hoặc đổi hàm mất mát sẽ tạo phép so sánh khác."))),
 S(B("71.3 — Discount old observations explicitly","71.3 — Giảm trọng số dữ liệu cũ tường minh"),
   B("In scalar ridge regression, x_t is one feature, y_t its target, A_t the discounted sum of squared features, and b_t the discounted feature–target sum. With forgetting factor ρ, each old contribution is multiplied by ρ before the new observation is added: A_t=ρA_{t−1}+x_t² and b_t=ρb_{t−1}+x_ty_t. The ridge estimate solves (A_t+λ)w_t=b_t, with λ>0 stabilizing the denominator. Equivalently it minimizes the discounted squared residual sum plus λw². ρ=1 never forgets; smaller ρ reduces the influence of old observations. This is an update rule, not evidence that forgetting improves prediction.",
   "Trong hồi quy ridge vô hướng, x_t là một đặc trưng, y_t là mục tiêu, A_t là tổng bình phương đặc trưng có giảm trọng số, còn b_t là tổng tích đặc trưng–mục tiêu. Với hệ số quên ρ, mỗi đóng góp cũ được nhân ρ trước khi thêm quan sát mới: A_t=ρA_{t−1}+x_t² và b_t=ρb_{t−1}+x_ty_t. Nghiệm ridge giải (A_t+λ)w_t=b_t, với λ>0 giúp ổn định mẫu số. Tương đương, nó tối thiểu hóa tổng bình phương phần dư giảm trọng số cộng λw². ρ=1 không quên; ρ nhỏ giảm ảnh hưởng dữ liệu cũ. Đây là quy tắc cập nhật, không phải bằng chứng quên giúp dự báo tốt hơn."),
   B("Set A₀=b₀=0, ρ=0.5, and λ=1. For observation 1, x₁=1,y₁=2 gives A₁=0.5·0+1²=1, b₁=0.5·0+1·2=2, and w₁=2/(1+1)=1. For observation 2, x₂=2,y₂=1 gives A₂=0.5·1+2²=4.5 and b₂=0.5·2+2·1=3. Thus w₂=3/(4.5+1)=6/11≈0.5455. The previous data contribution was halved before adding the new row; λ is added once to the denominator.",
   "Đặt A₀=b₀=0, ρ=0.5 và λ=1. Với quan sát 1, x₁=1,y₁=2 cho A₁=0.5·0+1²=1, b₁=0.5·0+1·2=2 và w₁=2/(1+1)=1. Với quan sát 2, x₂=2,y₂=1 cho A₂=0.5·1+2²=4.5 và b₂=0.5·2+2·1=3. Vậy w₂=3/(4.5+1)=6/11≈0.5455. Đóng góp cũ được giảm một nửa trước khi cộng hàng mới; λ chỉ cộng một lần vào mẫu số."),
   {"kind":"steps","title":B("Two discounted scalar updates","Hai bước cập nhật vô hướng có quên"),"caption":B("Exact inputs: A0=b0=0, rho=0.5, lambda=1; observations (x,y)=(1,2),(2,1). Each recurrence discounts the prior accumulator before adding the new row.","Đầu vào: A0=b0=0, rho=0.5, lambda=1; quan sát (x,y)=(1,2),(2,1). Mỗi truy hồi giảm tích lũy trước rồi mới cộng hàng mới."),"steps":[B("t=1: A=1, b=2, w=b/(A+lambda)=1","t=1: A=1, b=2, w=b/(A+lambda)=1"),B("t=2: A=0.5·1+4=4.5","t=2: A=0.5·1+4=4.5"),B("t=2: b=0.5·2+2=3","t=2: b=0.5·2+2=3"),B("w2=3/(4.5+1)=6/11≈0.5455","w2=3/(4.5+1)=6/11≈0.5455")]},
   [B("60 min — Differentiate the discounted scalar objective and show that its normal equation is (A_t+lambda)w=b_t.","60 phút — Lấy đạo hàm mục tiêu vô hướng có giảm trọng số và chứng minh phương trình chuẩn là (A_t+lambda)w=b_t."),B("60 min — Recompute A1,b1,w1 and A2,b2,w2 by hand from the exact two observations; keep rho and lambda in separate roles.","60 phút — Tính tay A1,b1,w1 rồi A2,b2,w2 từ đúng hai quan sát; phân biệt vai trò rho và lambda."),B("60 min — Implement the recurrence and assert intermediate accumulators [A1,b1]=[1,2], [A2,b2]=[4.5,3] before checking the final weight.","60 phút — Cài truy hồi và kiểm tra tích lũy trung gian [A1,b1]=[1,2], [A2,b2]=[4.5,3] trước khi kiểm tra trọng số cuối."),B("60 min — Repeat with rho=1 while keeping observations and lambda fixed; explain which old contribution changes and why one run cannot establish a better forecasting method.","60 phút — Lặp lại với rho=1, giữ quan sát và lambda; giải thích đóng góp cũ nào đổi và vì sao một lần chạy không chứng minh phương pháp dự báo tốt hơn.")],
   X("w71-d3-forgetting",B("Use A0=b0=0, rho=0.5, lambda=1 and observations (x1,y1)=(1,3),(x2,y2)=(2,0). Compute both accumulators and ridge weight after each row.","Dùng A0=b0=0, rho=0.5, lambda=1 và các quan sát (x1,y1)=(1,3),(x2,y2)=(2,0). Tính hai tích lũy và trọng số ridge sau mỗi hàng."),B("Apply A_t=rho A_{t−1}+x_t² and b_t=rho b_{t−1}+x_ty_t, then divide b_t by A_t+lambda.","Áp dụng A_t=rho A_{t−1}+x_t² và b_t=rho b_{t−1}+x_ty_t, rồi chia b_t cho A_t+lambda."),B("At t=1, A1=1,b1=3,w1=3/2=1.5. At t=2, A2=0.5·1+4=4.5 and b2=0.5·3+0=1.5, so w2=1.5/5.5=3/11≈0.2727. The zero second target adds feature information to A but no feature–target product to b; this is why the estimate moves toward zero.","Tại t=1, A1=1,b1=3,w1=3/2=1.5. Tại t=2, A2=0.5·1+4=4.5 và b2=0.5·3+0=1.5, nên w2=1.5/5.5=3/11≈0.2727. Mục tiêu thứ hai bằng 0 làm tăng thông tin đặc trưng trong A nhưng không thêm tích đặc trưng–mục tiêu vào b; vì thế ước lượng dịch về 0."))),
 S(B("71.4 — Define adaptation delay","71.4 — Định nghĩa độ trễ thích nghi"),
   B("A drift experiment declares a change origin, a stable reference error r, tolerance ε, and K consecutive origins before generating observations. These choices make recovery measurable instead of letting the analyst pick the first attractive point. For a scalar squared-loss learner, the gradient step on ½(θ−y)² is θ_{t+1}=θ_t+η(y_t−θ_t). A larger η reacts faster to a level change but can be noisier under varying targets. Adaptation delay is counted from the first post-change forecast to the end of the first run of K losses no greater than r+ε. Always show the loss path as well as the single delay.",
   "Thí nghiệm dịch chuyển phải khai báo mốc thay đổi, sai số tham chiếu ổn định r, dung sai ε và số mốc liên tiếp K trước khi sinh quan sát. Các lựa chọn này giúp đo phục hồi thay vì để nhà phân tích chọn điểm đẹp đầu tiên. Với bình phương sai số vô hướng ½(θ−y)², bước gradient là θ_{t+1}=θ_t+η(y_t−θ_t). η lớn phản ứng nhanh hơn với đổi mức nhưng có thể nhiễu hơn khi mục tiêu dao động. Độ trễ thích nghi được đếm từ dự báo đầu tiên sau thay đổi đến cuối chuỗi K tổn thất liên tiếp không vượt r+ε. Luôn trình bày cả đường tổn thất lẫn một con số độ trễ."),
   B("The target jumps from 0 to 4 and then stays at 4. Start θ₀=0 and use η=0.5. The four predictions before reveal are 0, 2, 3, and 3.5; after each reveal, update halfway toward 4. Squared losses are 16, 4, 1, and 0.25. Let the stable reference r=0, tolerance ε=1, and K=2. Losses at post-change origins 3 and 4 are both ≤1, so recovery is declared at origin 4, a delay of four origins. This toy rule does not say anything about real market drift.",
   "Mục tiêu nhảy từ 0 lên 4 rồi giữ nguyên. Bắt đầu θ₀=0, dùng η=0.5. Bốn dự báo trước khi mở kết quả là 0, 2, 3 và 3.5; sau mỗi lần mở, cập nhật nửa khoảng cách tới 4. Sai số bình phương là 16, 4, 1 và 0.25. Chọn tham chiếu ổn định r=0, dung sai ε=1, K=2. Tổn thất tại mốc sau dịch chuyển 3 và 4 đều ≤1, nên phục hồi được ghi nhận ở mốc 4, độ trễ bốn mốc. Quy tắc đồ chơi này không kết luận gì về dịch chuyển thị trường thật."),
   {"kind":"xy","title":B("Predictions approach a shifted target","Dự báo tiến gần mục tiêu đã dịch chuyển"),"caption":B("After a declared jump to y=4, eta=0.5 and theta0=0 produce predictions [0,2,3,3.5] at origins 1–4. The horizontal target is 4; values come directly from the stated update.","Sau khi khai báo mục tiêu nhảy tới y=4, eta=0.5 và theta0=0 cho dự báo [0,2,3,3.5] tại mốc 1–4. Mục tiêu ngang bằng 4; các điểm tính trực tiếp từ quy tắc đã nêu."),"xLabel":B("Post-change origin","Mốc sau dịch chuyển"),"yLabel":B("Prediction / target","Dự báo / mục tiêu"),"series":[{"name":B("Forecast before reveal","Dự báo trước khi mở kết quả"),"points":[[1,0],[2,2],[3,3],[4,3.5]],"mode":"line"},{"name":B("Target","Mục tiêu"),"points":[[1,4],[4,4]],"mode":"line"}]},
   [B("60 min — Derive the scalar gradient step from loss ½(theta−y)² and define what eta changes.","60 phút — Suy ra bước gradient vô hướng từ loss ½(theta−y)² và định nghĩa eta ảnh hưởng điều gì."),B("60 min — Starting at theta=0 with target 4 and eta=0.5, calculate each pre-reveal prediction and squared loss for four origins.","60 phút — Bắt đầu theta=0, mục tiêu 4, eta=0.5; tính từng dự báo trước khi mở kết quả và sai số bình phương trong bốn mốc."),B("60 min — Implement the update in a loop; assert predictions [0,2,3,3.5] and losses [16,4,1,0.25].","60 phút — Cài bước cập nhật trong vòng lặp; kiểm tra dự báo [0,2,3,3.5] và tổn thất [16,4,1,0.25]."),B("60 min — Apply r=0, epsilon=1, K=2 to the loss vector; mark the first qualifying pair and state why the choice must be frozen before generating data.","60 phút — Áp r=0, epsilon=1, K=2 vào vector tổn thất; đánh dấu cặp đầu đạt và nêu vì sao quy tắc phải khóa trước khi sinh dữ liệu.")],
   X("w71-d4-drift",B("A level changes from 0 to 6. Start theta=0; update theta_new=theta+0.5(y−theta) after each reveal. List predictions and squared losses for four post-change origins. With r=0, epsilon=1, and K=2, give the recovery origin and delay.","Mức mục tiêu đổi từ 0 lên 6. Bắt đầu theta=0; sau mỗi lần mở cập nhật theta_mới=theta+0.5(y−theta). Liệt kê dự báo và tổn thất bình phương trong bốn mốc sau đổi. Với r=0, epsilon=1, K=2, nêu mốc phục hồi và độ trễ."),B("Use each prediction as the next theta after moving halfway to 6. The first qualifying losses must be two consecutive values no greater than 1.","Dùng mỗi dự báo làm theta kế tiếp sau khi tiến nửa khoảng cách tới 6. Các tổn thất đạt đầu tiên phải là hai giá trị liên tiếp không quá 1."),B("Predictions are 0,3,4.5,5.25; squared losses against 6 are 36,9,2.25,0.5625. Only origin 4 qualifies so far, so K=2 has not been met and recovery has not yet occurred in the four-origin record. After origin 4 updates theta to 5.625, the fifth prediction has loss (6−5.625)²=0.140625. Origins 4 and 5 form the first qualifying pair; recovery is origin 5 with delay 5.","Dự báo là 0,3,4.5,5.25; sai số bình phương so với 6 là 36,9,2.25,0.5625. Hiện chỉ mốc 4 đạt, chưa đủ K=2 nên chưa phục hồi trong bốn mốc. Sau khi cập nhật ở mốc 4, theta thành 5.625; dự báo thứ năm có loss (6−5.625)²=0.140625. Mốc 4 và 5 là cặp đạt đầu tiên; phục hồi tại mốc 5, độ trễ 5."))),
 S(B("71.5 — Preserve chronology in evaluation","71.5 — Giữ trình tự trong đánh giá"),
   B("At each decision origin t, train data may include only labels revealed before t. An expanding window retains every eligible past row; a rolling window retains a declared recent block. A random split of time-ordered observations can train on tomorrow while evaluating yesterday. For a mean forecast, the training mean must be recomputed from the currently available prefix, not from all rows. Define the cutoff, update frequency, target horizon, and metric in advance. A small chronological test illustrates mechanics; two test points cannot establish reliable generalization or a trading edge.",
   "Ở mỗi mốc quyết định t, dữ liệu huấn luyện chỉ được chứa nhãn đã mở trước t. Cửa sổ mở rộng giữ mọi hàng quá khứ đủ điều kiện; cửa sổ trượt giữ một khối gần đây đã khai báo. Chia ngẫu nhiên dữ liệu theo thời gian có thể khiến mô hình học từ ngày mai để đánh giá hôm qua. Với dự báo trung bình, cần tính lại trung bình từ tiền tố hiện khả dụng, không dùng toàn bộ hàng. Khóa trước mốc cắt, tần suất cập nhật, chân trời mục tiêu và thước đo. Kiểm tra thời gian nhỏ chỉ minh họa cơ chế; hai điểm kiểm tra không chứng minh khả năng tổng quát hay lợi thế giao dịch."),
   B("Use the sequence [5,7,6,100,101]. Train on the first three rows: mean=(5+7+6)/3=6, so the origin-4 forecast is 6 and its squared error is (100−6)²=8836. Reveal 100, expand the training prefix, and refit: mean=(5+7+6+100)/4=29.5. The origin-5 forecast is 29.5 and squared error is (101−29.5)²=5112.25. Total test loss is 13948.25. A random split that uses 101 to forecast origin 4 violates the information cutoff.",
   "Dùng chuỗi [5,7,6,100,101]. Huấn luyện trên ba hàng đầu: trung bình=(5+7+6)/3=6, nên dự báo mốc 4 là 6 và sai số bình phương (100−6)²=8836. Mở 100, mở rộng tiền tố huấn luyện rồi khớp lại: trung bình=(5+7+6+100)/4=29.5. Dự báo mốc 5 là 29.5, sai số bình phương (101−29.5)²=5112.25. Tổng tổn thất kiểm tra là 13948.25. Chia ngẫu nhiên dùng 101 để dự báo mốc 4 vi phạm ranh giới thông tin."),
   {"kind":"matrix","title":B("What is available at the origin-4 forecast?","Thông tin nào có ở dự báo mốc 4?"),"caption":B("Rows are the supplied sequence. At origin 4 only values from origins 1–3 are in the training prefix; origins 4–5 are not available before their outcomes.","Các hàng là chuỗi đã cho. Tại mốc 4, tiền tố huấn luyện chỉ có giá trị mốc 1–3; kết quả mốc 4–5 chưa khả dụng."),"rows":["Origin 1","Origin 2","Origin 3","Origin 4","Origin 5"],"columns":["Observed value","Available at origin 4 (1/0)"],"values":[[5,1],[7,1],[6,1],[100,0],[101,0]]},
   [B("60 min — Draw the five observations on a timeline and mark the origin-4 cutoff before looking at errors.","60 phút — Vẽ năm quan sát trên trục thời gian và đánh dấu mốc cắt 4 trước khi xem sai số."),B("60 min — Compute the two expanding-prefix means and squared test losses from the supplied sequence by hand.","60 phút — Tính tay hai trung bình tiền tố mở rộng và sai số kiểm tra bình phương từ chuỗi đã cho."),B("60 min — Code an origin loop that fits on indices <t, predicts y_t, logs the cutoff, then reveals y_t; assert means 6 and 29.5.","60 phút — Viết vòng lặp theo mốc: khớp trên chỉ số <t, dự báo y_t, ghi mốc cắt rồi mới mở y_t; kiểm tra trung bình 6 và 29.5."),B("60 min — Demonstrate a random split that places value 101 in the training set for origin 4; explain exactly why the resulting score is invalid.","60 phút — Minh họa cách chia ngẫu nhiên đưa giá trị 101 vào tập huấn luyện khi dự báo mốc 4; giải thích chính xác vì sao điểm số đó không hợp lệ.")],
   X("w71-d5-chronology",B("For [2,4,3,9,11], use an expanding mean. Forecast origin 4 from the first three values, reveal 9, refit, then forecast origin 5. Give both predictions, squared losses, and total test loss. Identify one leakage mistake that random splitting could make.","Với [2,4,3,9,11], dùng trung bình mở rộng. Dự báo mốc 4 từ ba giá trị đầu, mở 9, khớp lại rồi dự báo mốc 5. Nêu hai dự báo, sai số bình phương và tổng kiểm tra. Chỉ ra một lỗi rò rỉ mà chia ngẫu nhiên có thể gây ra."),B("The first training mean uses [2,4,3]; the second uses those three plus the revealed 9. Do not include 11 before the origin-5 forecast.","Trung bình huấn luyện đầu dùng [2,4,3]; lần hai dùng ba số đó cộng 9 đã mở. Không đưa 11 vào trước dự báo mốc 5."),B("At origin 4, mean=(2+4+3)/3=3; loss=(9−3)²=36. After reveal, mean=(2+4+3+9)/4=4.5; origin-5 loss=(11−4.5)²=42.25. Total=78.25. A random split might train the origin-4 forecast on future value 11, which is unavailable at that decision and invalidates the evaluation.","Tại mốc 4, trung bình=(2+4+3)/3=3; loss=(9−3)²=36. Sau khi mở, trung bình=(2+4+3+9)/4=4.5; loss mốc 5=(11−4.5)²=42.25. Tổng=78.25. Chia ngẫu nhiên có thể huấn luyện dự báo mốc 4 bằng giá trị tương lai 11, vốn chưa có ở quyết định đó, khiến đánh giá sai.")))
 ],
 {"kind":"timeline","title":B("Observe → update → forecast again","Quan sát → cập nhật → dự báo tiếp"),"labels":[B("Issue forecast","Phát dự báo"),B("Reveal outcome","Mở kết quả"),B("Compute loss","Tính tổn thất"),B("Update learner","Cập nhật người học"),B("Advance origin","Tiến mốc")],"caption":B("The order is causal: each prediction is logged using only the available prefix before its target is revealed.","Trình tự mang tính nhân quả: mỗi dự báo được ghi bằng tiền tố hiện có trước khi mở mục tiêu tương ứng.")})

W72 = M(72,
 B("Week 72: Latent states, filtering, and smoothing","Tuần 72: Trạng thái ẩn, lọc và làm trơn"),
 B("A state-space model distinguishes a hidden state z_t from an observation y_t. A transition probability p(z_t|z_{t−1}) evolves the state; an emission or observation probability p(y_t|z_t) generates measurements. A filter reports p(z_t|y_{1:t}), using only observations available through t. A smoother reports p(z_t|y_{1:T}) and uses later observations too. In a finite-state filter, first predict by multiplying the previous state distribution by the transition matrix; then multiply each predicted probability by the current observation likelihood and normalize. In a scalar linear-Gaussian model, the Kalman gain is predicted state variance divided by predicted variance plus observation variance. Filtering supports real-time decisions; smoothing supports retrospective reconstruction but cannot be substituted into a historical forecast.",
   "Mô hình trạng thái không gian phân biệt trạng thái ẩn z_t với quan sát y_t. Xác suất chuyển tiếp p(z_t|z_{t−1}) mô tả trạng thái tiến triển; xác suất phát xạ/quan sát p(y_t|z_t) sinh phép đo. Bộ lọc báo p(z_t|y_{1:t}), chỉ dùng quan sát có đến t. Bộ làm trơn báo p(z_t|y_{1:T}) và dùng cả quan sát về sau. Với bộ lọc hữu hạn trạng thái, trước tiên dự báo bằng cách nhân phân phối trạng thái trước với ma trận chuyển tiếp; sau đó nhân mỗi xác suất dự báo với khả năng quan sát hiện tại rồi chuẩn hóa. Trong mô hình Gaussian tuyến tính vô hướng, Kalman gain bằng phương sai trạng thái dự báo chia cho tổng phương sai dự báo và phương sai quan sát. Lọc hỗ trợ quyết định thời gian thực; làm trơn hỗ trợ tái dựng hồi cứu nhưng không thể thay cho dự báo lịch sử."),
 [B("Propagate a prior through a transition matrix.","Truyền tiên nghiệm qua ma trận chuyển tiếp."),B("Update finite-state beliefs with an observation likelihood.","Cập nhật niềm tin hữu hạn trạng thái bằng khả năng quan sát."),B("Derive one scalar Kalman update with units and variances.","Suy ra một cập nhật Kalman vô hướng với đơn vị và phương sai."),B("Calculate how later evidence changes a smoothed state estimate.","Tính cách bằng chứng về sau đổi ước lượng trạng thái làm trơn."),B("Score only forecasts formed before their observations.","Chỉ chấm dự báo được lập trước quan sát tương ứng.")],
 [
 S(B("72.1 — Predict hidden states before observing","72.1 — Dự báo trạng thái ẩn trước khi quan sát"),
   B("Use two hidden regimes: C=calm and D=shifted. A probability vector [p(C),p(D)] sums to one. The transition matrix T has rows indexed by the previous state and columns by the next state; each row therefore sums to one. Before a new observation, the predicted distribution is p⁻_t=p_{t−1}T. The superscript minus means “before using y_t.” This multiplication propagates uncertainty about the state; it does not yet use the current measurement. State ordering and matrix orientation must be written down because transposing T changes the answer.",
   "Dùng hai chế độ ẩn: C=bình ổn và D=dịch chuyển. Vector xác suất [p(C),p(D)] có tổng bằng một. Hàng của ma trận chuyển tiếp T là trạng thái trước, cột là trạng thái kế tiếp; vì vậy mỗi hàng có tổng một. Trước quan sát mới, phân phối dự báo là p⁻_t=p_{t−1}T. Dấu trừ trên có nghĩa “trước khi dùng y_t.” Phép nhân truyền độ bất định về trạng thái nhưng chưa dùng phép đo hiện tại. Cần ghi thứ tự trạng thái và hướng ma trận vì chuyển vị T sẽ đổi đáp án."),
   B("At t−1 the belief is [P(C),P(D)]=[0.80,0.20]. Let T=[[0.90,0.10],[0.20,0.80]], where rows are previous C,D and columns next C,D. Then P⁻_t(C)=0.80·0.90+0.20·0.20=0.76 and P⁻_t(D)=0.80·0.10+0.20·0.80=0.24. The result [0.76,0.24] sums to one. No current observation likelihood has been applied yet.",
   "Tại t−1, niềm tin là [P(C),P(D)]=[0.80,0.20]. Dùng T=[[0.90,0.10],[0.20,0.80]], hàng là C,D trước đó và cột là C,D kế tiếp. Khi đó P⁻_t(C)=0.80·0.90+0.20·0.20=0.76 và P⁻_t(D)=0.80·0.10+0.20·0.80=0.24. Kết quả [0.76,0.24] có tổng một. Chưa nhân khả năng quan sát hiện tại."),
   {"kind":"matrix","title":B("Transition probabilities and predicted belief","Xác suất chuyển tiếp và niềm tin dự báo"),"caption":B("T=[[0.90,0.10],[0.20,0.80]], rows=previous C,D and columns=next C,D. Prior [0.80,0.20] gives prediction [0.76,0.24] before seeing the new measurement.","T=[[0.90,0.10],[0.20,0.80]], hàng là C,D trước đó và cột là C,D kế tiếp. Tiên nghiệm [0.80,0.20] cho dự báo [0.76,0.24] trước phép đo mới."),"rows":["Previous C / Trước C","Previous D / Trước D"],"columns":["Next C / Sau C","Next D / Sau D"],"values":[[0.9,0.1],[0.2,0.8]]},
   [B("60 min — Verify that both transition rows sum to 1 and identify what each row/column means.","60 phút — Kiểm tra tổng mỗi hàng chuyển tiếp bằng 1 và nêu ý nghĩa hàng/cột."),B("60 min — Multiply [0.80,0.20] by the stated matrix by hand; show both dot products rather than relying on software.","60 phút — Nhân tay [0.80,0.20] với ma trận đã cho; trình bày hai tích vô hướng thay vì dựa vào phần mềm."),B("60 min — Implement predict(prior,T); assert output [0.76,0.24], unit sum, and behavior for a prior concentrated on C.","60 phút — Cài predict(prior,T); kiểm tra [0.76,0.24], tổng bằng 1 và trường hợp tiên nghiệm tập trung ở C."),B("60 min — Swap the transition-matrix rows deliberately, recompute, and explain why the new answer corresponds to a different state convention.","60 phút — Cố ý đổi hàng ma trận chuyển tiếp, tính lại và giải thích vì sao kết quả mới ứng với quy ước trạng thái khác.")],
   X("w72-d1-predict",B("Use prior [P(C),P(D)]=[0.70,0.30] and T=[[0.80,0.20],[0.10,0.90]] (rows previous C,D; columns next C,D). Compute the predicted next-state distribution.","Dùng tiên nghiệm [P(C),P(D)]=[0.70,0.30] và T=[[0.80,0.20],[0.10,0.90]] (hàng C,D trước, cột C,D sau). Tính phân phối trạng thái kế tiếp dự báo."),B("Multiply the prior by each column: next C uses 0.70·0.80+0.30·0.10; next D uses 0.70·0.20+0.30·0.90.","Nhân tiên nghiệm với từng cột: C kế tiếp dùng 0.70·0.80+0.30·0.10; D kế tiếp dùng 0.70·0.20+0.30·0.90."),B("P⁻(C)=0.56+0.03=0.59. P⁻(D)=0.14+0.27=0.41. The probabilities sum to one. This is a prediction from the transition model only; an observation update would require state-conditional likelihoods.","P⁻(C)=0.56+0.03=0.59. P⁻(D)=0.14+0.27=0.41. Tổng xác suất bằng một. Đây chỉ là dự báo từ mô hình chuyển tiếp; cập nhật quan sát cần khả năng có điều kiện theo trạng thái."))),
 S(B("72.2 — Reweight with the current observation","72.2 — Tái trọng số bằng quan sát hiện tại"),
   B("A measurement is more or less likely under each hidden state. If p⁻_t(j) is the predicted probability of state j and L_j=p(y_t|z_t=j) is the current observation likelihood, the unnormalized posterior weight is q_j=p⁻_t(j)L_j. Divide every q_j by Z=Σ_jq_j, the probability of the observed measurement under the model. This Bayes update keeps probabilities nonnegative and makes them sum to one. A likelihood is not a posterior: it must be combined with the prior prediction. Tiny Z can signal a surprising observation or a model that assigns it almost no probability.",
   "Phép đo có thể dễ xảy ra hơn dưới trạng thái ẩn này so với trạng thái khác. Nếu p⁻_t(j) là xác suất dự báo trạng thái j và L_j=p(y_t|z_t=j) là khả năng của quan sát hiện tại, trọng số hậu nghiệm chưa chuẩn hóa là q_j=p⁻_t(j)L_j. Chia mỗi q_j cho Z=Σ_jq_j, xác suất của quan sát theo mô hình. Cập nhật Bayes giữ xác suất không âm và tổng bằng một. Khả năng không phải hậu nghiệm: phải kết hợp với tiên nghiệm dự báo. Z rất nhỏ có thể cho thấy quan sát lạ hoặc mô hình gán xác suất gần bằng không cho nó."),
   B("Continue from prior prediction [C,D]=[0.76,0.24]. A positive shift alarm has likelihoods [P(y|C),P(y|D)]=[0.10,0.80]. Unnormalized weights are [0.76·0.10,0.24·0.80]=[0.076,0.192]; Z=0.268. The filtered posterior is [0.076/0.268,0.192/0.268]=[0.2836,0.7164]. It favors D because the alarm is eight times as likely under D as C, while still accounting for the prior.",
   "Tiếp tục từ dự báo [C,D]=[0.76,0.24]. Cảnh báo dịch chuyển dương tính có khả năng [P(y|C),P(y|D)]=[0.10,0.80]. Trọng số chưa chuẩn hóa là [0.76·0.10,0.24·0.80]=[0.076,0.192]; Z=0.268. Hậu nghiệm đã lọc là [0.076/0.268,0.192/0.268]=[0.2836,0.7164]. Nó nghiêng về D vì cảnh báo có khả năng xảy ra ở D cao gấp tám lần C, đồng thời vẫn tính đến tiên nghiệm."),
   {"kind":"bars","title":B("Prior prediction and filtered posterior","Tiên nghiệm dự báo và hậu nghiệm đã lọc"),"caption":B("Exact state probabilities: prior prediction C,D=[0.76,0.24]; current alarm likelihoods=[0.10,0.80]; normalized posterior=[0.2836,0.7164].","Xác suất trạng thái: tiên nghiệm dự báo C,D=[0.76,0.24]; khả năng cảnh báo hiện tại=[0.10,0.80]; hậu nghiệm chuẩn hóa=[0.2836,0.7164]."),"xLabel":B("State and stage","Trạng thái và bước"),"yLabel":B("Probability","Xác suất"),"values":[{"label":B("C prior","C trước"),"value":0.76},{"label":B("D prior","D trước"),"value":0.24},{"label":B("C filtered","C đã lọc"),"value":0.2836},{"label":B("D filtered","D đã lọc"),"value":0.7164}]},
   [B("60 min — Separate the transition prediction from the observation likelihood; write the four supplied probabilities in a table.","60 phút — Tách dự báo chuyển tiếp khỏi khả năng quan sát; ghi bốn xác suất đã cho vào bảng."),B("60 min — Compute q_C, q_D, Z, and both posterior entries by hand to four decimal places.","60 phút — Tính tay q_C, q_D, Z và hai thành phần hậu nghiệm đến bốn chữ số thập phân."),B("60 min — Implement an update that checks likelihoods are nonnegative and normalizes q; assert posterior sum 1 and [0.2836,0.7164].","60 phút — Cài cập nhật kiểm tra likelihood không âm và chuẩn hóa q; xác nhận tổng hậu nghiệm 1 và [0.2836,0.7164]."),B("60 min — Change only the alarm likelihood under D from 0.80 to 0.20; recompute and explain why evidence strength, not transition, changed.","60 phút — Chỉ đổi khả năng cảnh báo dưới D từ 0.80 thành 0.20; tính lại và giải thích vì sao sức mạnh bằng chứng đổi chứ không phải chuyển tiếp.")],
   X("w72-d2-filter",B("Use predicted probabilities [C,D]=[0.60,0.40] and likelihoods for a quiet observation [P(y|C),P(y|D)]=[0.70,0.20]. Compute the normalized filtered posterior.","Dùng xác suất dự báo [C,D]=[0.60,0.40] và khả năng quan sát yên tĩnh [P(y|C),P(y|D)]=[0.70,0.20]. Tính hậu nghiệm đã lọc chuẩn hóa."),B("Multiply statewise to get unnormalized weights, sum them for Z, then divide each weight by Z.","Nhân theo từng trạng thái để có trọng số chưa chuẩn hóa, cộng ra Z rồi chia mỗi trọng số cho Z."),B("Weights are [0.60·0.70,0.40·0.20]=[0.42,0.08]; Z=0.50. Posterior=[0.42/0.50,0.08/0.50]=[0.84,0.16]. It shifts toward C because quiet evidence is more likely under C; the prior still contributes to both weights.","Trọng số là [0.60·0.70,0.40·0.20]=[0.42,0.08]; Z=0.50. Hậu nghiệm=[0.42/0.50,0.08/0.50]=[0.84,0.16]. Xác suất nghiêng về C vì bằng chứng yên tĩnh dễ xảy ra dưới C; tiên nghiệm vẫn góp vào cả hai trọng số."))),
 S(B("72.3 — A scalar Kalman update","72.3 — Cập nhật Kalman vô hướng"),
   B("For a scalar linear-Gaussian state, x is the hidden level, P its variance, Q process-noise variance, and R observation-noise variance. With transition x_t=F x_{t−1}+noise, predict x⁻=F x and P⁻=F²P+Q. The Kalman gain K=P⁻/(P⁻+R) lies between zero and one when variances are positive. Update x=x⁻+K(y−x⁻): move the prediction toward the measurement by a fraction of the innovation. Update variance P=(1−K)P⁻. Larger measurement noise R lowers K; larger predicted uncertainty P⁻ raises it. Variances have squared state units.",
   "Với trạng thái Gaussian tuyến tính vô hướng, x là mức ẩn, P là phương sai của nó, Q là phương sai nhiễu quá trình, R là phương sai nhiễu quan sát. Với chuyển tiếp x_t=F x_{t−1}+nhiễu, dự báo x⁻=F x và P⁻=F²P+Q. Kalman gain K=P⁻/(P⁻+R) nằm giữa 0 và 1 khi phương sai dương. Cập nhật x=x⁻+K(y−x⁻): dịch dự báo về phép đo một phần của innovation. Phương sai cập nhật P=(1−K)P⁻. R lớn làm K giảm; bất định dự báo P⁻ lớn làm K tăng. Phương sai có đơn vị bình phương của trạng thái."),
   B("Start with prior mean x=0 and variance P=1. Use F=1, Q=1, observation y=4, and R=3. Prediction gives x⁻=1·0=0 and P⁻=1²·1+1=2. Gain K=2/(2+3)=0.4. Innovation y−x⁻=4, so updated mean x=0+0.4·4=1.6. Updated variance is (1−0.4)·2=1.2. The measurement moves the mean upward, but nonzero R leaves uncertainty instead of setting the state exactly to 4.",
   "Bắt đầu trung bình tiên nghiệm x=0, phương sai P=1. Dùng F=1, Q=1, quan sát y=4, R=3. Dự báo cho x⁻=1·0=0 và P⁻=1²·1+1=2. Gain K=2/(2+3)=0.4. Innovation y−x⁻=4, nên trung bình cập nhật x=0+0.4·4=1.6. Phương sai cập nhật=(1−0.4)·2=1.2. Phép đo kéo trung bình lên, nhưng R khác không giữ lại bất định thay vì đặt trạng thái đúng bằng 4."),
   {"kind":"steps","title":B("Scalar Kalman predict and update","Dự báo và cập nhật Kalman vô hướng"),"caption":B("Inputs x=0,P=1,F=1,Q=1,y=4,R=3 give predicted (x−,P−)=(0,2), gain 0.4, updated (x,P)=(1.6,1.2). Variances are squared state units.","Đầu vào x=0,P=1,F=1,Q=1,y=4,R=3 cho dự báo (x−,P−)=(0,2), gain 0.4, cập nhật (x,P)=(1.6,1.2). Phương sai có đơn vị bình phương trạng thái."),"steps":[B("Predict mean: x−=F·x=1·0=0","Dự báo trung bình: x−=F·x=1·0=0"),B("Predict variance: P−=F²P+Q=1²·1+1=2","Dự báo phương sai: P−=F²P+Q=1²·1+1=2"),B("Gain: K=P−/(P−+R)=2/5=0.4; innovation=4−0=4","Gain: K=P−/(P−+R)=2/5=0.4; innovation=4−0=4"),B("Update mean=0+0.4·4=1.6; variance=(1−0.4)·2=1.2","Cập nhật trung bình=0+0.4·4=1.6; phương sai=(1−0.4)·2=1.2")]},
   [B("60 min — Define x,P,Q,R,F and annotate which quantities are variances rather than standard deviations.","60 phút — Định nghĩa x,P,Q,R,F và ghi rõ đại lượng nào là phương sai chứ không phải độ lệch chuẩn."),B("Derive P−, K, updated mean, and updated variance using exactly (0,1,1,1,4,3). Explain the sign of the innovation.","60 phút — Suy ra P−, K, trung bình và phương sai cập nhật từ đúng (0,1,1,1,4,3). Giải thích dấu innovation."),B("Implement scalar_filter_step and assert predicted variance 2, gain 0.4, mean 1.6, and variance 1.2.","60 phút — Cài scalar_filter_step và kiểm tra phương sai dự báo 2, gain 0.4, trung bình 1.6, phương sai 1.2."),B("Run the same prior and observation with R=12; compare gains and updated means, then explain why noisier measurement receives less weight.","60 phút — Chạy cùng tiên nghiệm và quan sát với R=12; so gain và trung bình cập nhật, giải thích vì sao phép đo nhiễu hơn nhận trọng số thấp hơn.")],
   X("w72-d3-kalman",B("Use x=2,P=4,F=1,Q=1,y=5,R=1. Calculate prediction, Kalman gain, updated mean, and updated variance.","Dùng x=2,P=4,F=1,Q=1,y=5,R=1. Tính dự báo, Kalman gain, trung bình và phương sai cập nhật."),B("First compute x−=Fx and P−=F²P+Q. Then use K=P−/(P−+R) and the innovation y−x−.","Trước hết tính x−=Fx và P−=F²P+Q. Sau đó dùng K=P−/(P−+R) và innovation y−x−."),B("Prediction: x−=2 and P−=5. Gain K=5/(5+1)=5/6. Innovation=5−2=3, so updated mean=2+(5/6)·3=4.5. Updated variance=(1−5/6)·5=5/6. The mean moves most of the way toward y because prior uncertainty is large relative to R.","Dự báo: x−=2 và P−=5. Gain K=5/(5+1)=5/6. Innovation=5−2=3, nên trung bình cập nhật=2+(5/6)·3=4.5. Phương sai cập nhật=(1−5/6)·5=5/6. Trung bình tiến gần y vì bất định tiên nghiệm lớn so với R."))),
 S(B("72.4 — Filtering now, smoothing later","72.4 — Lọc hiện tại, làm trơn sau"),
   B("A filter for time t conditions on observations y₁,…,y_t. A smoother for that same state also conditions on y_{t+1},…,y_T. To smooth in a finite-state model, start with the filtered state weights at t and multiply by the likelihood of future evidence conditional on each possible state at t; normalize again. That future likelihood includes transitions from t to later states. Smoothing can improve retrospective state reconstruction, but it is not available at decision time t. Replacing a logged filter probability with a later smoother changes the information set and leaks future evidence into a historical forecast.",
   "Bộ lọc tại thời điểm t điều kiện theo y₁,…,y_t. Bộ làm trơn cho cùng trạng thái còn điều kiện theo y_{t+1},…,y_T. Để làm trơn mô hình hữu hạn trạng thái, bắt đầu từ trọng số đã lọc ở t rồi nhân với khả năng của bằng chứng tương lai có điều kiện theo từng trạng thái tại t; sau đó chuẩn hóa lại. Khả năng tương lai bao gồm chuyển tiếp từ t sang thời điểm sau. Làm trơn có thể cải thiện tái dựng trạng thái hồi cứu nhưng không có sẵn tại quyết định t. Thay xác suất lọc đã ghi bằng kết quả làm trơn về sau làm đổi tập thông tin và rò rỉ bằng chứng tương lai vào dự báo lịch sử."),
   B("Use T=[[0.9,0.1],[0.2,0.8]], initial [C,D]=[0.8,0.2], and a positive observation at t=1 with likelihood [0.1,0.8]. Prediction is [0.76,0.24]; filtering gives D probability 0.24·0.8/(0.76·0.1+0.24·0.8)=48/67≈0.7164. At t=2 observe a quiet signal with likelihood [0.8,0.2] under next states C,D. Its future likelihood given state C at t=1 is 0.9·0.8+0.1·0.2=0.74; given D it is 0.2·0.8+0.8·0.2=0.32. Smoothing gives P(D₁|y₁,y₂)=0.7164·0.32/(0.2836·0.74+0.7164·0.32)=768/1471≈0.5221. The later quiet signal revises the historical state estimate downward.",
   "Dùng T=[[0.9,0.1],[0.2,0.8]], tiên nghiệm [C,D]=[0.8,0.2], và quan sát dương tại t=1 có khả năng [0.1,0.8]. Dự báo là [0.76,0.24]; lọc cho xác suất D là 0.24·0.8/(0.76·0.1+0.24·0.8)=48/67≈0.7164. Tại t=2 quan sát tín hiệu yên tĩnh có khả năng [0.8,0.2] dưới trạng thái kế tiếp C,D. Khả năng tương lai khi trạng thái tại t=1 là C bằng 0.9·0.8+0.1·0.2=0.74; khi D là 0.2·0.8+0.8·0.2=0.32. Làm trơn cho P(D₁|y₁,y₂)=0.7164·0.32/(0.2836·0.74+0.7164·0.32)=768/1471≈0.5221. Tín hiệu yên tĩnh về sau điều chỉnh giảm ước lượng trạng thái lịch sử."),
   {"kind":"bars","title":B("State probability at t=1","Xác suất trạng thái tại t=1"),"caption":B("With the stated two-state transition and observations, filtering at t=1 gives P(D1|y1)=48/67≈0.7164; after the t=2 quiet observation, smoothing gives P(D1|y1,y2)=768/1471≈0.5221. Only the first was available at t=1.","Với chuyển tiếp hai trạng thái và quan sát đã nêu, lọc tại t=1 cho P(D1|y1)=48/67≈0.7164; sau quan sát yên tĩnh t=2, làm trơn cho P(D1|y1,y2)=768/1471≈0.5221. Chỉ giá trị đầu có tại t=1."),"xLabel":B("Estimate","Ước lượng"),"yLabel":B("Probability of shifted state D","Xác suất trạng thái dịch chuyển D"),"values":[{"label":B("Filter, at t=1","Lọc, tại t=1"),"value":48/67},{"label":B("Smoother, after t=2","Làm trơn, sau t=2"),"value":768/1471}]},
   [B("60 min — Put y1 and y2 on a timeline; mark which one a decision at t=1 is allowed to use.","60 phút — Đặt y1 và y2 trên trục thời gian; đánh dấu quan sát nào quyết định tại t=1 được phép dùng."),B("60 min — Reproduce the filtered 48/67, then calculate each future likelihood 0.74 and 0.32 from the transition rows.","60 phút — Tính lại 48/67 đã lọc rồi tính từng khả năng tương lai 0.74 và 0.32 từ hàng chuyển tiếp."),B("60 min — Compute the smoother numerator for C and D, normalize to 768/1471, and annotate every factor with its source.","60 phút — Tính tử số làm trơn cho C và D, chuẩn hóa thành 768/1471 và ghi nguồn từng thừa số."),B("60 min — Write two report labels, 'real-time filter' and 'retrospective smoother'; explain why only the first can be scored as an origin-1 forecast.","60 phút — Viết hai nhãn báo cáo 'bộ lọc thời gian thực' và 'bộ làm trơn hồi cứu'; giải thích vì sao chỉ nhãn đầu được chấm là dự báo mốc 1.")],
   X("w72-d4-smooth",B("Keep the same initial belief, transition matrix, and positive y1 from the lesson, so the filtered probability of D1 is 48/67. At t=2, instead observe a positive signal with likelihood [P(y2|C2),P(y2|D2)]=[0.2,0.9]. Compute the future likelihood conditional on C1 and D1, then the smoothed probability P(D1|y1,y2).","Giữ tiên nghiệm, ma trận chuyển tiếp và quan sát dương y1 như bài, nên xác suất đã lọc của D1 là 48/67. Tại t=2, thay bằng tín hiệu dương có khả năng [P(y2|C2),P(y2|D2)]=[0.2,0.9]. Tính khả năng tương lai có điều kiện theo C1,D1 rồi tính P(D1|y1,y2) đã làm trơn."),B("Given C1, mix [0.2,0.9] using transition row [0.9,0.1]; given D1, use [0.2,0.8]. Weight those two likelihoods by filtered probabilities [19/67,48/67] and normalize.","Khi C1, gộp [0.2,0.9] theo hàng chuyển tiếp [0.9,0.1]; khi D1, dùng [0.2,0.8]. Nhân hai khả năng đó với xác suất đã lọc [19/67,48/67] rồi chuẩn hóa."),B("Future likelihood is 0.9·0.2+0.1·0.9=0.27 given C1, and 0.2·0.2+0.8·0.9=0.76 given D1. The smoothed D probability is (48/67·0.76)/((19/67·0.27)+(48/67·0.76))=36.48/41.61≈0.8767. The later positive signal raises the retrospective estimate from 0.7164, but it still was unavailable at t=1.","Khả năng tương lai là 0.9·0.2+0.1·0.9=0.27 khi C1 và 0.2·0.2+0.8·0.9=0.76 khi D1. Xác suất D đã làm trơn là (48/67·0.76)/((19/67·0.27)+(48/67·0.76))=36.48/41.61≈0.8767. Tín hiệu dương về sau làm tăng ước lượng hồi cứu từ 0.7164 nhưng vẫn chưa có tại t=1."))),
 S(B("72.5 — Evaluate information available at forecast time","72.5 — Đánh giá theo thông tin có lúc dự báo"),
   B("A proper forecast score compares a probability issued before an event with the event later observed. For a binary event z∈{0,1}, Brier loss is (p−z)², where p is the forecast probability of event 1. If state filtering predicts the next observation, compute its probability by summing over the predicted next-state distribution and each state's emission likelihood. A smoother conditions on the event itself or later data, so scoring it as a forecast of that event is circular. Keep separate columns for forecast probability, reveal time, observed outcome, and score; retrospective state accuracy is a different estimand.",
   "Điểm dự báo hợp lệ so sánh xác suất đã phát trước sự kiện với sự kiện được quan sát sau. Với sự kiện nhị phân z∈{0,1}, Brier loss là (p−z)², trong đó p là xác suất dự báo sự kiện 1. Nếu bộ lọc trạng thái dự báo quan sát kế tiếp, tính xác suất bằng cách cộng phân phối trạng thái kế tiếp nhân khả năng phát xạ của từng trạng thái. Bộ làm trơn điều kiện theo chính sự kiện hoặc dữ liệu về sau, nên chấm nó như dự báo cho sự kiện đó là lập luận vòng tròn. Giữ riêng cột xác suất dự báo, lúc mở, kết quả quan sát và điểm; độ đúng của trạng thái hồi cứu là đại lượng khác."),
   B("From the filtered D probability at t=1, [C,D]=[19/67,48/67]. Transition predicts D₂ with probability 19/67·0.10+48/67·0.80=40.3/67≈0.6015 and C₂ with probability 26.7/67≈0.3985. For the t=2 positive alarm with emission likelihood [0.10,0.80], forecast P(alarm₂=1|y₁)=(26.7·0.10+40.3·0.80)/67=34.91/67≈0.5210. The realized signal is quiet, z=0, so Brier loss=(0.5210−0)²≈0.2715. The t=2 smoother for D₁ uses that quiet signal and cannot replace this already-issued probability.",
   "Từ xác suất D đã lọc tại t=1, phân phối [C,D]=[19/67,48/67]. Chuyển tiếp dự báo D₂ có xác suất 19/67·0.10+48/67·0.80=40.3/67≈0.6015 và C₂ là 26.7/67≈0.3985. Với cảnh báo dương t=2 có khả năng phát xạ [0.10,0.80], dự báo P(cảnh báo₂=1|y₁)=(26.7·0.10+40.3·0.80)/67=34.91/67≈0.5210. Tín hiệu thực tế yên tĩnh, z=0, nên Brier loss=(0.5210−0)²≈0.2715. Bộ làm trơn D₁ tại t=2 dùng tín hiệu yên tĩnh đó và không thể thay xác suất đã phát trước."),
   {"kind":"bars","title":B("One-step alarm forecast and observed event","Dự báo cảnh báo một bước và sự kiện quan sát"),"caption":B("Using unrounded filtered probabilities, predicted alarm probability is 34.91/67≈0.5210; the later quiet observation is z=0. Brier loss is (0.5210−0)^2≈0.2715. Smoother at t=2 is not a valid forecast of this reveal.","Dùng xác suất đã lọc chưa làm tròn, xác suất cảnh báo dự báo là 34.91/67≈0.5210; quan sát sau là tín hiệu yên tĩnh z=0. Brier loss=(0.5210−0)^2≈0.2715. Kết quả làm trơn tại t=2 không phải dự báo hợp lệ cho quan sát này."),"xLabel":B("Quantity","Đại lượng"),"yLabel":B("Probability / binary outcome","Xác suất / kết quả nhị phân"),"values":[{"label":B("Forecast P(alarm)","Dự báo P(cảnh báo)"),"value":34.91/67},{"label":B("Observed quiet (0)","Quan sát yên tĩnh (0)"),"value":0}]},
   [B("60 min — For a binary outcome z, derive why the Brier contribution is (p−z)² for z=0 and z=1.","60 phút — Với kết quả nhị phân z, suy ra vì sao Brier contribution là (p−z)² khi z=0 và z=1."),B("60 min — Recompute P(D2), P(C2), and P(alarm2) from the filtered distribution; retain fractions until the final decimal.","60 phút — Tính lại P(D2), P(C2) và P(cảnh báo2) từ phân phối đã lọc; giữ phân số tới bước thập phân cuối."),B("60 min — Compute the Brier loss for the supplied quiet outcome and write a row with origin, forecast, reveal, outcome, and loss.","60 phút — Tính Brier loss cho kết quả yên tĩnh đã cho và viết một hàng gồm mốc, dự báo, lúc mở, kết quả, loss."),B("60 min — Put the filtered and smoothed D1 estimates side by side and label their information cutoffs; do not score the smoother as a t=1 forecast.","60 phút — Đặt ước lượng D1 đã lọc và làm trơn cạnh nhau, ghi ranh giới thông tin; không chấm bộ làm trơn như dự báo t=1.")],
   X("w72-d5-brier",B("A binary filter issues p=[0.2,0.7,0.6] before outcomes z=[0,1,0]. Calculate each Brier loss and their mean. State why a smoothed probability that uses each z cannot be reported as this forecast score.","Bộ lọc nhị phân phát p=[0.2,0.7,0.6] trước các kết quả z=[0,1,0]. Tính từng Brier loss và trung bình. Nêu vì sao xác suất làm trơn dùng từng z không thể báo như điểm dự báo này."),B("Use (p−z)² row by row, then average three losses. Check that each p was recorded before its matching outcome.","Dùng (p−z)² từng hàng rồi lấy trung bình ba loss. Kiểm tra mỗi p được ghi trước kết quả tương ứng."),B("Losses are (0.2−0)²=0.04, (0.7−1)²=0.09, and (0.6−0)²=0.36. Mean Brier loss=(0.04+0.09+0.36)/3=0.49/3≈0.1633. A smoother conditioned on the outcomes has already seen information being scored, so it measures retrospective reconstruction rather than forecast quality.","Loss là (0.2−0)²=0.04, (0.7−1)²=0.09 và (0.6−0)²=0.36. Brier trung bình=(0.04+0.09+0.36)/3=0.49/3≈0.1633. Bộ làm trơn đã điều kiện theo chính kết quả được chấm nên đo tái dựng hồi cứu, không phải chất lượng dự báo.")))
 ],
 {"kind":"flow","title":B("Filter by the present; smooth with the future","Lọc bằng hiện tại; làm trơn bằng tương lai"),"labels":[B("Prior belief","Niềm tin tiên nghiệm"),B("Transition prediction","Dự báo chuyển tiếp"),B("Current observation","Quan sát hiện tại"),B("Filtered state","Trạng thái đã lọc"),B("Later observations","Quan sát về sau"),B("Smoothed state","Trạng thái đã làm trơn")],"caption":B("Filtering stops at the current information cutoff; smoothing revises a past state using later evidence.","Lọc dừng ở ranh giới thông tin hiện tại; làm trơn điều chỉnh trạng thái quá khứ bằng bằng chứng về sau.")})

W73=M(73,B("Week 73: Select a reproducible research claim","Tuần 73: Chọn tuyên bố nghiên cứu có thể tái lập"),
 B("A paper title is not an estimand. A replicable claim names a method, comparator, data-generating or market regime, prediction target, horizon, metric, and conditions. A feasibility review asks whether the implementation and data are inspectable, the license permits the planned use, and a small test fits the available time and compute. Scorecards can help prioritize candidates, but access and permission are hard gates rather than compensating points. Reproduction is evidence about whether a specified procedure can be rerun; it is not endorsement of a result. Keep the final claim narrower than the available evidence.",
 "Tiêu đề bài báo không phải đại lượng cần ước lượng. Tuyên bố có thể tái lập phải nêu phương pháp, đối chứng, chế độ sinh dữ liệu/thị trường, mục tiêu dự báo, chân trời, thước đo và điều kiện. Đánh giá khả thi hỏi liệu triển khai và dữ liệu có kiểm tra được, giấy phép có cho phép cách dùng dự kiến, và thử nghiệm nhỏ có vừa thời gian/tính toán không. Bảng điểm giúp ưu tiên ứng viên, nhưng quyền truy cập và giấy phép là điều kiện bắt buộc, không phải điểm có thể bù. Tái lập là bằng chứng về khả năng chạy lại quy trình cụ thể; không đồng nghĩa tán thành kết quả. Tuyên bố cuối phải hẹp hơn bằng chứng hiện có."),
 [B("Translate broad claims into a testable tuple.","Chuyển tuyên bố rộng thành bộ điều kiện kiểm tra được."),B("Separate feasibility evidence from quality scores.","Tách bằng chứng khả thi khỏi điểm chất lượng."),B("Define a minimal reproduction artifact and comparator.","Định nghĩa tạo phẩm tái lập tối thiểu và đối chứng."),B("Budget a pilot and decide before inspecting outcomes.","Lập ngân sách thí điểm và quyết định trước khi xem kết quả."),B("Write a bounded go/no-go decision without endorsing the claim.","Viết quyết định tiếp tục/dừng có giới hạn, không tán thành tuyên bố.")],
 [
 S(B("73.1 — A claim is a tuple, not a title","73.1 — Tuyên bố là bộ điều kiện, không phải tiêu đề"),B("Operationalize a claim as (population/regime, method, comparator, outcome, horizon, conditions). Every entry narrows what a result can support. “Works in volatile markets” leaves regime thresholds, baseline, target, and horizon undefined. An estimand is the quantity the study intends to compare, such as mean one-step squared loss over a declared shifted regime. Before running code, write what would count as evidence against the claim too; otherwise a negative result can be redefined away. This exercise uses only a supplied toy case, not an external paper.","Chuyển tuyên bố thành (quần thể/chế độ, phương pháp, đối chứng, kết quả, chân trời, điều kiện). Mỗi mục thu hẹp phạm vi kết luận. “Hoạt động trong thị trường biến động” chưa định nghĩa ngưỡng chế độ, đối chứng, mục tiêu hay chân trời. Đại lượng cần ước lượng là lượng nghiên cứu muốn so sánh, chẳng hạn sai số bình phương một bước trung bình trong chế độ dịch chuyển đã khai báo. Trước khi chạy mã, hãy nêu cả bằng chứng nào bác bỏ tuyên bố; nếu không, kết quả âm tính có thể bị diễn giải lại để né tránh. Bài này chỉ dùng ca đồ chơi cho sẵn, không cần bài báo bên ngoài."),B("The broad phrase is “adaptive method M improves forecasts in volatile conditions.” Make it testable as follows: population=the supplied 8-point synthetic series; method=M with update rule θ←θ+0.5(y−θ); comparator=persistence; outcome=one-step squared error; horizon=one observation; volatile condition=the four origins after the supplied level change from 0 to 4. The primary comparison is the mean paired loss difference on those four origins. A falsifier is mean loss difference ≤0. This tuple defines one test only; it cannot support a universal market claim.","Cụm rộng là “phương pháp thích nghi M cải thiện dự báo khi biến động.” Viết thành phép kiểm: quần thể=chuỗi tổng hợp 8 điểm đã cho; phương pháp=M với quy tắc θ←θ+0.5(y−θ); đối chứng=dự báo bền vững; kết quả=sai số bình phương một bước; chân trời=một quan sát; chế độ biến động=bốn mốc sau khi mức chuỗi đổi từ 0 lên 4. So sánh chính là chênh lệch tổn thất ghép cặp trung bình trên bốn mốc đó. Điều bác bỏ là chênh lệch tổn thất trung bình ≤0. Bộ điều kiện này chỉ xác định một phép thử, không chứng minh tuyên bố phổ quát về thị trường."),{"kind":"steps","title":B("Turn the claim into a test","Chuyển tuyên bố thành phép thử"),"caption":B("The supplied toy claim fixes all six fields: 8 synthetic points, adaptive M, persistence, one-step squared loss, four post-change origins, and falsifier mean improvement ≤0.","Tuyên bố đồ chơi đã khóa sáu mục: 8 điểm tổng hợp, M thích nghi, đối chứng bền vững, bình phương sai số một bước, bốn mốc sau đổi và điều bác bỏ cải thiện trung bình ≤0."),"steps":[B("Population: 8 supplied synthetic points","Quần thể: 8 điểm tổng hợp đã cho"),B("Method / comparator: M / persistence","Phương pháp / đối chứng: M / bền vững"),B("Outcome / horizon: squared loss / one step","Kết quả / chân trời: bình phương sai số / một bước"),B("Regime / falsifier: 4 shifted origins / improvement ≤0","Chế độ / bác bỏ: 4 mốc dịch chuyển / cải thiện ≤0")]},
 [B("60 min — Label the six fields in the supplied phrase; write one sentence for every field that was missing.","60 phút — Gắn nhãn sáu thành phần trong câu đã cho; viết một câu cho mỗi thành phần còn thiếu."),B("60 min — Using the exact definition above, write the estimand and the falsifier before calculating any model output.","60 phút — Dùng đúng định nghĩa trên, viết đại lượng cần ước lượng và điều bác bỏ trước khi tính đầu ra mô hình."),B("60 min — Create a machine-readable claim card with the six fields, units, time boundary, and an explicit blank for the falsification condition.","60 phút — Tạo phiếu tuyên bố đọc được bằng máy gồm sáu mục, đơn vị, ranh giới thời gian và ô riêng cho điều bác bỏ."),B("60 min — Ask a peer to identify one sentence that overstates the supplied toy evidence; replace it with a narrower claim and preserve both versions.","60 phút — Nhờ bạn học tìm một câu nói quá bằng chứng đồ chơi; thay bằng tuyên bố hẹp hơn và giữ cả hai phiên bản.")],X("w73-d1-claim",B("Operationalize “method A is better in a high-noise regime” using a supplied 6-point synthetic sequence. Specify population, method, comparator, outcome, horizon, regime rule, and one falsifier. Do not invent results.","Cụ thể hóa “phương pháp A tốt hơn trong chế độ nhiễu cao” bằng chuỗi tổng hợp 6 điểm cho sẵn. Nêu quần thể, phương pháp, đối chứng, kết quả, chân trời, quy tắc chế độ và một điều bác bỏ. Không bịa kết quả."),B("Define high noise using a generator parameter before examining method losses. Use the same origins and metric for A and its comparator.","Định nghĩa nhiễu cao bằng tham số bộ sinh trước khi xem tổn thất. Dùng cùng mốc và thước đo cho A và đối chứng."),B("One valid specification is: population=the 6 supplied draws from a generator with σ=2; method=A; comparator=persistence; outcome=mean one-step squared loss; horizon=1; regime=σ fixed at 2; falsifier=loss_A−loss_persistence≥0. The condition is testable because the generator and comparator are fixed. It supports only this synthetic regime, not real deployment.","Một đặc tả hợp lệ: quần thể=6 mẫu đã cho từ bộ sinh σ=2; phương pháp=A; đối chứng=bền vững; kết quả=sai số bình phương một bước trung bình; chân trời=1; chế độ=σ cố định bằng 2; điều bác bỏ=loss_A−loss_bền_vững≥0. Điều kiện kiểm tra được vì bộ sinh và đối chứng đã khóa. Nó chỉ hỗ trợ chế độ tổng hợp này, không chứng minh triển khai thực tế."))),
 S(B("73.2 — Feasibility gates precede a score","73.2 — Cổng khả thi đi trước điểm số"),B("A weighted rubric is a transparent prioritization device, not an objective truth meter. Ratings and weights can summarize claim clarity, code observability, permitted data access, and independent testability. Compute Σw_js_j only after stating each scale and weight. A missing data license or inaccessible required input is a hard feasibility failure; it cannot be offset by a high code score. Separate “not verified” from “poor quality”: absent evidence is uncertainty, not evidence that a paper is bad. Keep a source note for every factual rating.","Bảng chấm có trọng số là công cụ ưu tiên minh bạch, không phải máy đo sự thật khách quan. Điểm và trọng số có thể tóm tắt độ rõ tuyên bố, khả năng kiểm tra mã, quyền dữ liệu và khả năng kiểm tra độc lập. Chỉ tính Σw_js_j sau khi nêu thang và trọng số. Thiếu giấy phép dữ liệu hoặc đầu vào bắt buộc không truy cập được là lỗi khả thi cứng; điểm mã cao không bù được. Phân biệt “chưa xác minh” với “chất lượng thấp”: thiếu bằng chứng là bất định, không phải bằng chứng bài kém. Ghi nguồn cho từng điểm sự kiện."),B("Rate one supplied candidate on four 0–5 criteria with weights [0.30,0.25,0.25,0.20]. Ratings [4,3,5,2] mean claim clarity 4, code observability 3, data access 5, independent testability 2. The total is 0.30·4+0.25·3+0.25·5+0.20·2=1.20+0.75+1.25+0.40=3.60/5. Now add the stated fact that reuse permission for the required raw data is unresolved. The score remains 3.60, but the candidate is not yet eligible for a release requiring those data; the gate and score answer different questions.","Chấm một ứng viên cho sẵn theo bốn tiêu chí 0–5, trọng số [0.30,0.25,0.25,0.20]. Điểm [4,3,5,2] lần lượt là độ rõ tuyên bố 4, khả năng quan sát mã 3, truy cập dữ liệu 5, kiểm tra độc lập 2. Tổng là 0.30·4+0.25·3+0.25·5+0.20·2=1.20+0.75+1.25+0.40=3.60/5. Thêm dữ kiện quyền dùng lại dữ liệu thô bắt buộc chưa rõ. Điểm vẫn 3.60 nhưng ứng viên chưa đủ điều kiện phát hành nếu cần dữ liệu ấy; cổng và điểm trả lời hai câu hỏi khác nhau."),{"kind":"bars","title":B("Weighted ratings with an unresolved rights gate","Điểm có trọng số và cổng quyền chưa rõ"),"caption":B("The bars are the exact 0–5 ratings [4,3,5,2]; weights [0.30,0.25,0.25,0.20] give 3.60/5. Data reuse permission is unresolved, a separate hard gate.","Các cột là điểm 0–5 chính xác [4,3,5,2]; trọng số [0.30,0.25,0.25,0.20] cho tổng 3.60/5. Quyền dùng lại dữ liệu chưa rõ là cổng cứng riêng."),"xLabel":B("Criterion","Tiêu chí"),"yLabel":B("Rating out of 5","Điểm trên 5"),"values":[{"label":B("Claim clarity","Độ rõ tuyên bố"),"value":4},{"label":B("Code observable","Mã kiểm tra được"),"value":3},{"label":B("Data access","Truy cập dữ liệu"),"value":5},{"label":B("Independent test","Kiểm tra độc lập"),"value":2}]},
 [B("60 min — Define each 0–5 rating anchor in one phrase; state what observation would earn a 0, 3, or 5 for code access.","60 phút — Định nghĩa mỗi mốc 0–5 bằng một cụm; nêu bằng chứng để chấm 0, 3 hoặc 5 cho khả năng truy cập mã."),B("60 min — Multiply the four ratings by their paired weights and show each product before summing to 3.60.","60 phút — Nhân bốn điểm với trọng số tương ứng, ghi từng tích rồi cộng thành 3.60."),B("60 min — Build a rubric function plus a separate Boolean rights gate; test that raising a non-rights score never turns a blocked candidate eligible.","60 phút — Viết hàm chấm và cổng quyền Boolean riêng; kiểm tra tăng điểm khác không thể biến ứng viên bị chặn thành đủ điều kiện."),B("60 min — Write a two-paragraph selection memo distinguishing score, verified fact, unknown, and hard blocker.","60 phút — Viết memo chọn bài hai đoạn, tách điểm, sự kiện xác minh, điều chưa biết và trở ngại cứng.")],X("w73-d2-gate",B("Weights are [0.4,0.3,0.2,0.1] and ratings [5,2,4,3]. Compute the score. Required data are public but the license explicitly forbids redistribution; can you publish the dataset with your reproduction?","Trọng số [0.4,0.3,0.2,0.1], điểm [5,2,4,3]. Tính tổng. Dữ liệu bắt buộc công khai nhưng giấy phép cấm phân phối lại; bạn có được đăng bộ dữ liệu cùng bản tái lập không?"),B("Compute paired products. Public visibility is not the same as redistribution permission.","Tính tích tương ứng. Nhìn thấy công khai không đồng nghĩa được phép phân phối lại."),B("Score=0.4·5+0.3·2+0.2·4+0.1·3=2+0.6+0.8+0.3=3.7/5. No: the explicit license forbids redistribution. You may link to the permitted source or seek an allowed access path, but must not bundle the data; the score cannot override the legal gate.","Tổng=0.4·5+0.3·2+0.2·4+0.1·3=2+0.6+0.8+0.3=3.7/5. Không: giấy phép nêu rõ cấm phân phối lại. Có thể liên kết nguồn được phép hoặc tìm cách truy cập hợp lệ, nhưng không được đóng gói dữ liệu; điểm không vượt qua cổng pháp lý."))),
 S(B("73.3 — Reproduction starts with a minimal artifact","73.3 — Tái lập bắt đầu bằng tạo phẩm tối thiểu"),B("A reproduction can be scoped as a claim card, data provenance, preprocessing, reference baseline, primary metric, run configuration, and generated output. First reproduce plumbing on a hand-checkable fixture, then try the declared central result. An implementation that cannot be matched to equations is not a faithful baseline. A readme without an executable command is not a clean reproduction path. Use the supplied fictional study below so the exercise is self-contained; a paper’s own claims would need separate verification.","Có thể giới hạn tái lập thành phiếu tuyên bố, nguồn dữ liệu, tiền xử lý, đối chứng tham chiếu, thước đo chính, cấu hình chạy và đầu ra sinh. Trước tiên tái lập luồng xử lý bằng fixture tính tay được, sau đó mới thử kết quả trọng tâm đã khai báo. Triển khai không đối chiếu được với phương trình thì chưa phải đối chứng trung thành. README không có lệnh chạy thì chưa phải đường tái lập sạch. Bài dùng nghiên cứu hư cấu đã cung cấp để tự đầy đủ; tuyên bố trong bài thật vẫn cần xác minh riêng."),B("The fictional method predicts the running mean: m_t=(m_{t−1}·(t−1)+y_t)/t. Its declared comparator is the previous observation. On fixture targets [2,4,3], the method's forecasts at origins 1–3 are [0,2,3] if m₀=0; persistence forecasts [0,2,4]. Squared losses are 4+4+0=8 for the running mean and 4+4+1=9 for persistence. This fixture checks the code against the stated recurrence; the running mean happens to beat this tiny comparator, but that is not a population result.","Phương pháp hư cấu dự báo trung bình lũy tiến: m_t=(m_{t−1}·(t−1)+y_t)/t. Đối chứng đã nêu là quan sát trước. Với mục tiêu fixture [2,4,3], dự báo của phương pháp tại mốc 1–3 là [0,2,3] nếu m₀=0; persistence dự báo [0,2,4]. Bình phương sai số lần lượt 4+4+0=8 cho trung bình lũy tiến và 4+4+1=9 cho persistence. Fixture kiểm mã theo truy hồi đã nêu; trung bình lũy tiến tình cờ thắng đối chứng nhỏ này nhưng đây không phải kết quả quần thể."),{"kind":"xy","title":B("Fictional method versus persistence on the fixture","Phương pháp hư cấu so với persistence trên fixture"),"caption":B("Targets [2,4,3], running-mean forecasts [0,2,3], persistence forecasts [0,2,4]; losses are 8 and 9 respectively. m0=0 is supplied, and all values are toy units.","Mục tiêu [2,4,3], dự báo trung bình lũy tiến [0,2,3], persistence [0,2,4]; tổn thất lần lượt 8 và 9. Cho m0=0; mọi giá trị là đơn vị đồ chơi."),"xLabel":B("Origin","Mốc"),"yLabel":B("Target units","Đơn vị mục tiêu"),"series":[{"name":B("Target","Mục tiêu"),"points":[[1,2],[2,4],[3,3]],"mode":"line"},{"name":B("Running mean","Trung bình lũy tiến"),"points":[[1,0],[2,2],[3,3]],"mode":"line"},{"name":B("Persistence","Persistence"),"points":[[1,0],[2,2],[3,4]],"mode":"line"}]},
 [B("60 min — Copy the fictional recurrence and identify the initial state m0 and target y_t; specify the first forecast convention.","60 phút — Chép truy hồi hư cấu, xác định trạng thái đầu m0 và mục tiêu y_t; nêu quy ước dự báo đầu."),B("60 min — Trace all six forecasts and compute squared losses for the two methods on [2,4,3].", "60 phút — Truy sáu dự báo và tính bình phương sai số cho hai phương pháp trên [2,4,3]."),B("60 min — Write a two-method function with identical input arrays and assert loss totals 8 and 5; retain per-origin rows.","60 phút — Viết hàm hai phương pháp dùng cùng mảng đầu vào, kiểm tra tổng 8 và 5; giữ kết quả từng mốc."),B("60 min — Draft a reproduction card with equation, fixture, command, expected output, license field, and the limitation that this fixture is not empirical evidence.","60 phút — Soạn phiếu tái lập gồm phương trình, fixture, lệnh, đầu ra kỳ vọng, mục giấy phép và giới hạn fixture không phải bằng chứng thực nghiệm.")],X("w73-d3-artifact",B("For the same recurrence m_t=(m_{t−1}(t−1)+y_t)/t, m0=0, targets [1,5], compute the forecast sequence and cumulative squared loss. Persistence begins with 0.","Với cùng truy hồi m_t=(m_{t−1}(t−1)+y_t)/t, m0=0, mục tiêu [1,5], tính chuỗi dự báo và tổng bình phương sai số. Persistence bắt đầu từ 0."),B("At origin 1 both methods forecast 0. Reveal 1 before computing the origin-2 running mean; the updated mean is 1.","Tại mốc 1 cả hai dự báo 0. Mở 1 trước khi tính trung bình lũy tiến mốc 2; trung bình cập nhật là 1."),B("Running mean forecasts [0,1]; losses are (0−1)²=1 and (1−5)²=16, total 17. Persistence forecasts [0,1]; its losses are also 1 and 16, total 17. They tie on this two-point fixture. The result checks arithmetic, not a general ranking.","Trung bình lũy tiến dự báo [0,1]; loss là (0−1)²=1 và (1−5)²=16, tổng 17. Persistence dự báo [0,1], loss cũng 1 và 16, tổng 17. Hai phương pháp hòa trên fixture hai điểm. Kết quả kiểm tra số học, không xếp hạng tổng quát."))),
 S(B("73.4 — A pilot tests the reproduction path","73.4 — Thí điểm kiểm tra đường tái lập"),B("A pilot answers whether a specified task can be run within constraints, not whether its scientific hypothesis is true. Freeze a small fixture, command, software environment, elapsed-time rule, and stopping condition. Preserve failures and distinguish setup failure from model failure. Estimate wall time using repeated runs and include data acquisition or preprocessing if those are part of the planned workflow. A pilot that is changed after seeing its output becomes exploratory; record the change rather than treating it as a predeclared test.","Thí điểm trả lời tác vụ xác định có chạy được trong ràng buộc hay không, không kiểm chứng giả thuyết khoa học. Khóa fixture nhỏ, lệnh, môi trường phần mềm, cách đo thời gian và điều kiện dừng. Giữ lần chạy thất bại và phân biệt lỗi thiết lập với lỗi mô hình. Ước lượng thời gian tường qua nhiều lần, gồm lấy dữ liệu/tiền xử lý nếu chúng thuộc quy trình dự kiến. Thí điểm đổi sau khi xem đầu ra trở thành khám phá; cần ghi thay đổi thay vì giả vờ đã định trước."),B("A four-run pilot on the supplied toy package takes [3,4,5,4] minutes, including startup. Mean is 4 minutes; projected 20-run cost is 80 minutes only under a linear-scaling assumption. The package has 12 rows and 1 missing target; the declared missing-target rule is “exclude before fitting,” leaving 11 eligible rows. The stop rule is 10 minutes per run or any missing feature timestamp. All four runs meet the time rule and none has the timestamp failure, so the pilot is feasible under this narrow specification.","Thí điểm bốn lần trên gói đồ chơi cho thời gian [3,4,5,4] phút gồm khởi động. Trung bình 4 phút; dự phóng 20 lần thành 80 phút chỉ đúng nếu thời gian tăng tuyến tính. Gói có 12 hàng và 1 mục tiêu thiếu; quy tắc đã nêu là “loại trước khi khớp”, còn 11 hàng đủ điều kiện. Quy tắc dừng là 10 phút mỗi lần hoặc thiếu mốc thời gian của đặc trưng. Cả bốn lần đều đạt giới hạn thời gian và không lần nào thiếu mốc, nên thí điểm khả thi theo đặc tả hẹp này."),{"kind":"bars","title":B("Four measured pilot runtimes","Bốn thời gian thí điểm đo được"),"caption":B("Runs took [3,4,5,4] minutes including startup; the stop threshold is 10 minutes. Twelve rows contain one missing target, so 11 remain after the stated exclusion.","Bốn lần chạy mất [3,4,5,4] phút gồm khởi động; ngưỡng dừng là 10 phút. Mười hai hàng có một mục tiêu thiếu, nên còn 11 sau khi loại theo quy tắc."),"xLabel":B("Pilot run","Lần thí điểm"),"yLabel":B("Minutes","Phút"),"values":[{"label":B("Run 1","Lần 1"),"value":3},{"label":B("Run 2","Lần 2"),"value":4},{"label":B("Run 3","Lần 3"),"value":5},{"label":B("Run 4","Lần 4"),"value":4}]},
 [B("60 min — Write the pilot's stop rule, run unit, and included overhead before reading the four timings.","60 phút — Ghi quy tắc dừng, đơn vị đo và phần phụ phí trước khi xem bốn thời gian."),B("60 min — Calculate the mean, linear 20-run projection, and eligible row count; explicitly state each assumption.","60 phút — Tính trung bình, dự phóng tuyến tính 20 lần và số hàng hợp lệ; nêu rõ từng giả định."),B("60 min — Implement the 12-row missing-target filter and add a failing assertion for a missing feature timestamp.","60 phút — Cài bộ lọc mục tiêu thiếu trên 12 hàng và thêm assertion thất bại khi thiếu mốc đặc trưng."),B("60 min — Decide go/no-go for this pilot using only the predeclared 10-minute and timestamp criteria; list what the pilot does not establish.","60 phút — Quyết định tiếp tục/dừng chỉ theo tiêu chí 10 phút và mốc thời gian đã định; liệt kê điều thí điểm chưa chứng minh.")],X("w73-d4-pilot",B("A second toy pilot records runtimes [8,11,7] minutes with a 10-minute stop threshold and 20 rows, 2 missing targets. Apply the stop rule, compute mean runtime, and give the eligible row count using the same exclusion rule.","Thí điểm đồ chơi thứ hai có thời gian [8,11,7] phút, ngưỡng dừng 10 phút, 20 hàng và 2 mục tiêu thiếu. Áp quy tắc dừng, tính thời gian trung bình và số hàng hợp lệ theo quy tắc loại tương tự."),B("One run exceeds 10 minutes, so the stop criterion triggers even though the mean may be below 10. Exclude both missing-target rows before fitting.","Một lần vượt 10 phút nên kích hoạt tiêu chí dừng dù trung bình có thể dưới 10. Loại hai hàng thiếu mục tiêu trước khi khớp."),B("Mean runtime=(8+11+7)/3=26/3≈8.67 minutes; eligible rows=20−2=18. The pilot is no-go under the predeclared rule because run 2 took 11>10 minutes. The passing average cannot cancel a per-run stop condition; profile the slow run and repeat only under a documented revised pilot.","Thời gian trung bình=(8+11+7)/3=26/3≈8.67 phút; số hàng hợp lệ=20−2=18. Thí điểm không đạt theo quy tắc định trước vì lần 2 mất 11>10 phút. Trung bình đạt không xóa điều kiện dừng từng lần; hãy phân tích lần chậm và chỉ lặp theo thí điểm sửa đổi có ghi chép."))),
 S(B("73.5 — Make a bounded selection decision","73.5 — Quyết định chọn có giới hạn"),B("A selection decision should report verified facts, unknowns, hard gates, and the next test separately. A numerical rubric can order candidates only after eligibility is checked. The most useful decision may be “defer until rights are clarified” rather than “choose the highest score.” State the opportunity cost and the smallest action that can resolve uncertainty. An honest narrow scope makes a reproduction feasible; it does not claim that a method is state of the art or that a career path is guaranteed.","Quyết định chọn cần báo riêng sự kiện đã xác minh, điều chưa biết, cổng bắt buộc và phép thử kế tiếp. Bảng số chỉ xếp ứng viên sau khi kiểm điều kiện. Quyết định hữu ích có thể là “hoãn đến khi làm rõ quyền” thay vì “chọn điểm cao nhất.” Nêu chi phí cơ hội và hành động nhỏ nhất giải quyết bất định. Phạm vi hẹp trung thực giúp tái lập khả thi; nó không tuyên bố phương pháp tối tân hay đảm bảo nghề nghiệp."),B("Two fictional candidates have rubric scores 4.1 and 3.7 out of 5. Candidate A has a runnable baseline but required data rights unresolved; candidate B has a lower score, a clear permitted 11-row toy dataset, and a four-hour reproduction fixture. The hard gate makes A ineligible for the proposed public release. Choose B for a bounded reproduction, disclose the narrow data regime, and reserve 2 hours to ask whether A has an allowed data route. This is a scope decision, not a scientific ranking.","Hai ứng viên hư cấu có điểm 4.1 và 3.7/5. A có đối chứng chạy được nhưng quyền dữ liệu bắt buộc chưa rõ; B điểm thấp hơn, có bộ dữ liệu đồ chơi 11 hàng được phép và fixture tái lập bốn giờ. Cổng bắt buộc khiến A chưa đủ điều kiện phát hành công khai dự kiến. Chọn B cho tái lập giới hạn, công bố chế độ dữ liệu hẹp và dành 2 giờ hỏi A có đường dữ liệu hợp lệ không. Đây là quyết định phạm vi, không phải xếp hạng khoa học."),{"kind":"steps","title":B("Eligibility first, then priority","Điều kiện trước, ưu tiên sau"),"caption":B("Candidate A scores 4.1/5 but rights are unresolved. Candidate B scores 3.7/5, has permitted 11-row data and a 4-hour fixture; choose B for this bounded public reproduction.","Ứng viên A đạt 4.1/5 nhưng quyền chưa rõ. B đạt 3.7/5, có dữ liệu 11 hàng được phép và fixture 4 giờ; chọn B cho bản tái lập công khai có giới hạn này."),"steps":[B("A: 4.1/5; rights gate unresolved → blocked","A: 4.1/5; quyền chưa rõ → bị chặn"),B("B: 3.7/5; permitted data → eligible","B: 3.7/5; dữ liệu được phép → đủ điều kiện"),B("Select B for the bounded public task","Chọn B cho tác vụ công khai có giới hạn"),B("Ask one question to resolve A's data route","Hỏi một câu để làm rõ đường dữ liệu của A")]},
 [B("60 min — Fill a decision table with score, permission, runnable fixture, hours, and unresolved question for A and B.","60 phút — Điền bảng quyết định gồm điểm, quyền, fixture chạy được, giờ và câu hỏi chưa rõ cho A,B."),B("60 min — Apply the hard gate before ranking; write one-sentence rationales for selecting B and deferring A.","60 phút — Áp cổng bắt buộc trước khi xếp hạng; viết lý do một câu chọn B và hoãn A."),B("60 min — Draft a scope card for B: one claim, one comparator, the 11-row data regime, and the 4-hour fixture.","60 phút — Soạn phiếu phạm vi cho B: một tuyên bố, một đối chứng, chế độ dữ liệu 11 hàng và fixture bốn giờ."),B("60 min — Write the exact permission question for A and a stop condition if no valid data route exists.","60 phút — Viết câu hỏi quyền chính xác cho A và điều kiện dừng nếu không có đường dữ liệu hợp lệ.")],X("w73-d5-choice",B("Candidate A scores 4.5/5 but its code cannot run without a paid service. Candidate B scores 3.8/5 and has a reproducible, permitted fixture that fits 6 hours. Your public reproduction budget is 8 hours and no paid services are allowed. Which do you choose and what claim boundary do you state?","A đạt 4.5/5 nhưng mã cần dịch vụ trả phí mới chạy. B đạt 3.8/5, có fixture được phép tái lập trong 6 giờ. Ngân sách tái lập công khai là 8 giờ, không được dùng dịch vụ trả phí. Chọn ai và nêu giới hạn tuyên bố nào?"),B("Apply feasibility rules first: both time and permitted resources must fit. A's score cannot override the paid-service constraint.","Áp quy tắc khả thi trước: thời gian và tài nguyên được phép đều phải vừa. Điểm A không vượt ràng buộc cấm dịch vụ trả phí."),B("Choose B: its 6-hour fixture fits the 8-hour budget and uses permitted resources. State only that you reproduced the specified fixture under its supplied conditions; do not claim it validates performance beyond that regime. Record A as deferred because its paid dependency violates the task constraint, not because its score is low.","Chọn B: fixture sáu giờ vừa ngân sách tám giờ và dùng tài nguyên được phép. Chỉ nói bạn tái lập fixture theo điều kiện đã cho; không tuyên bố xác nhận hiệu năng ngoài chế độ ấy. Ghi A là hoãn vì phụ thuộc trả phí vi phạm ràng buộc tác vụ, không phải vì điểm thấp.")))
 ],{"kind":"matrix","title":B("Claim, evidence, and feasibility gates","Tuyên bố, bằng chứng và cổng khả thi"),"labels":["method","comparator","data / rights","outcome","scope"],"caption":B("A selection is defensible when the claim is bounded, artifacts are inspectable, and access gates are satisfied.","Lựa chọn có thể bảo vệ khi tuyên bố có giới hạn, tạo phẩm kiểm tra được và cổng truy cập được đáp ứng.")})

W74=M(74,B("Week 74: Freeze a reproduction protocol","Tuần 74: Khóa quy trình tái lập"),
 B("A protocol is a dated specification written before the main outcomes are examined. It fixes the estimand, eligible data snapshot, chronological split, preprocessing, comparator configurations, metric, aggregation, exclusions, and compute budget. A holdout must remain untouched until the declared final evaluation. Acceptance means the procedure ran as specified and outputs can be traced; it does not require a positive effect. Changes made after access to outcomes need a dated amendment and exploratory label for affected decisions. A synthetic fixture tests the harness but cannot validate the external scientific claim.","Quy trình là đặc tả có ngày viết trước khi xem kết quả chính. Nó khóa đại lượng cần ước lượng, ảnh chụp dữ liệu đủ điều kiện, chia theo thời gian, tiền xử lý, cấu hình đối chứng, thước đo, cách gộp, loại trừ và ngân sách tính toán. Tập giữ lại phải nguyên vẹn tới lần đánh giá cuối đã khai báo. Chấp nhận nghĩa là chạy đúng đặc tả và truy vết được đầu ra; không yêu cầu hiệu ứng dương. Thay đổi sau khi xem kết quả cần phụ lục có ngày và gắn nhãn khám phá cho quyết định liên quan. Fixture tổng hợp kiểm tra bộ chạy nhưng không xác nhận tuyên bố khoa học bên ngoài."),
 [B("Specify the estimand and data boundary before results.","Nêu đại lượng và ranh giới dữ liệu trước kết quả."),B("Encode chronological splits and preprocessing as deterministic rules.","Mã hóa chia thời gian và tiền xử lý thành quy tắc xác định."),B("Freeze baselines, metrics, aggregation, and exclusions.","Khóa đối chứng, thước đo, cách gộp và loại trừ."),B("Test the protocol harness on fixtures and preserve amendments.","Kiểm thử bộ quy trình bằng fixture và lưu phụ lục sửa đổi."),B("Classify final outputs as confirmatory or exploratory.","Phân loại đầu ra cuối thành xác nhận hoặc khám phá.")],
 [
 S(B("74.1 — Define the question before the data","74.1 — Định nghĩa câu hỏi trước dữ liệu"),B("An estimand specifies what quantity a study intends to learn. For one-step forecast evaluation, it might be the mean paired squared-loss difference between method and baseline over origins 101–120. The protocol must identify target availability, forecast origin, regime, and unit. A hypothesis is not the same as the estimand: “method improves” predicts a sign, while the estimand defines the number whose sign will be examined. Fix exclusions and missing-value rules before measuring so rows are not removed because they weaken a result.","Đại lượng cần ước lượng nêu lượng nghiên cứu muốn biết. Với đánh giá dự báo một bước, đó có thể là chênh lệch bình phương sai số ghép cặp trung bình giữa phương pháp và đối chứng trên mốc 101–120. Quy trình phải nêu lúc mục tiêu khả dụng, mốc dự báo, chế độ và đơn vị. Giả thuyết khác đại lượng: “phương pháp cải thiện” dự đoán dấu; đại lượng định nghĩa con số sẽ xem dấu. Khóa quy tắc loại trừ và giá trị thiếu trước khi đo để không loại hàng vì nó làm yếu kết quả."),B("The protocol defines d_t=loss_method,t−loss_base,t on origins t=101,…,120, with target y_{t+1} known only after the forecast. The estimand is Δ=(1/20)Σd_t in squared-target units. The directional hypothesis is Δ<0. Origins with missing y_{t+1} are excluded only under a predeclared rule; if exactly 2 are missing, the denominator becomes 18 and both exclusions are logged. This defines an observable question without assuming the method wins.","Quy trình định nghĩa d_t=loss_method,t−loss_base,t trên mốc t=101,…,120, mục tiêu y_{t+1} chỉ được biết sau dự báo. Đại lượng là Δ=(1/20)Σd_t, đơn vị bình phương mục tiêu. Giả thuyết hướng là Δ<0. Mốc thiếu y_{t+1} chỉ bị loại theo quy tắc định trước; nếu thiếu đúng 2, mẫu số thành 18 và ghi cả hai. Câu hỏi quan sát được mà không giả định phương pháp thắng."),{"kind":"steps","title":B("Estimand versus hypothesis","Đại lượng và giả thuyết"),"caption":B("Origins 101–120 define 20 paired differences d_t=loss(method)−loss(base); Δ is their mean and the directional prediction is Δ<0.","Mốc 101–120 định nghĩa 20 sai khác d_t=loss(phương pháp)−loss(đối chứng); Δ là trung bình và dự đoán hướng là Δ<0."),"steps":[B("Freeze eligible origins 101–120","Khóa mốc đủ điều kiện 101–120"),B("Compute each paired difference d_t","Tính từng sai khác ghép cặp d_t"),B("Average: Δ=(1/20)Σd_t","Lấy trung bình: Δ=(1/20)Σd_t"),B("Test prediction Δ<0; retain negative results","Kiểm tra dự đoán Δ<0; giữ kết quả âm tính")]},
 [B("60 min — Write a one-line estimand with population, unit, horizon, and comparator for the provided 20-origin case.","60 phút — Viết đại lượng một dòng gồm quần thể, đơn vị, chân trời và đối chứng cho 20 mốc đã cho."),B("60 min — Distinguish the numeric target Δ from the directional statement Δ<0; compute Δ for paired differences [−1,2,−2,1].","60 phút — Phân biệt số Δ với phát biểu hướng Δ<0; tính Δ cho sai khác [−1,2,−2,1]."),B("60 min — Implement a protocol object that validates start/end origins, missing-target denominator, and one-step horizon.","60 phút — Cài đối tượng quy trình kiểm tra mốc đầu/cuối, mẫu số khi thiếu mục tiêu và chân trời một bước."),B("60 min — Write an exclusion log for two missing outcomes and show how the denominator is recorded rather than silently changed.","60 phút — Viết nhật ký loại hai kết quả thiếu, cho thấy mẫu số được ghi chứ không đổi âm thầm.")],X("w74-d1-estimand",B("A protocol has four paired differences [1,−3,−2,0], defined as method loss minus baseline loss. Compute the mean estimand and decide whether the directional prediction Δ<0 is supported on this toy sample. State one limit.","Quy trình có bốn sai khác ghép cặp [1,−3,−2,0], định nghĩa loss phương pháp trừ loss đối chứng. Tính đại lượng trung bình và quyết định dự đoán Δ<0 có được ủng hộ trong mẫu đồ chơi không. Nêu một giới hạn."),B("Add all four signed differences before dividing by four; a negative sample mean is evidence for the prediction only on these cases.","Cộng bốn sai khác có dấu rồi chia bốn; trung bình mẫu âm chỉ hỗ trợ dự đoán trên các ca này."),B("Sum=1−3−2+0=−4, so Δ=−4/4=−1. The toy sample points in the predicted direction Δ<0. Four paired origins do not establish a population effect, and any dependence or post-hoc selection must be reported.","Tổng=1−3−2+0=−4, nên Δ=−4/4=−1. Mẫu đồ chơi đi theo hướng dự đoán Δ<0. Bốn mốc ghép cặp không xác lập hiệu ứng quần thể; cần báo cáo phụ thuộc hoặc chọn mẫu hậu nghiệm."))),
 S(B("74.2 — Freeze the chronological split","74.2 — Khóa cách chia theo thời gian"),B("For a forecast made at origin t, training features and labels must have been available by t; a target occurring later cannot enter fitting or preprocessing. Define train, validation, and holdout by timestamps, not random row numbers. Any scaler, imputer, or feature selector must be fitted on training data only and applied forward. Purging overlapping labels may be required when target windows share outcomes. Write the exact boundary inclusivity so two implementations cannot disagree about whether a row belongs to a split.","Với dự báo tại mốc t, đặc trưng và nhãn huấn luyện phải khả dụng tới t; mục tiêu xảy ra sau không được dùng trong khớp hay tiền xử lý. Định nghĩa train, validation và holdout bằng dấu thời gian, không phải số hàng ngẫu nhiên. Bộ chuẩn hóa, điền thiếu hay chọn đặc trưng phải khớp chỉ trên train rồi áp dụng về sau. Có thể cần purge nhãn chồng lấn khi cửa sổ mục tiêu dùng chung kết quả. Ghi rõ biên có bao gồm hay không để hai triển khai không bất đồng hàng thuộc tập nào."),B("Given timestamps 1–12 and one-step targets, set training origins 1–6, validation 7–8, holdout 9–10; origins 11–12 lack a next target and are excluded. Use half-open intervals [1,7), [7,9), [9,11). A feature published at time 8.5 cannot be used for validation origin 8; it may first be used at origin 9. The row belongs to neither training nor origin-8 features until its publication time is reached.","Với dấu thời gian 1–12 và mục tiêu một bước, đặt mốc huấn luyện 1–6, validation 7–8, holdout 9–10; mốc 11–12 thiếu mục tiêu kế tiếp nên loại. Dùng khoảng nửa mở [1,7), [7,9), [9,11). Đặc trưng công bố lúc 8.5 không dùng được cho validation mốc 8; sớm nhất dùng tại mốc 9. Hàng đó không thuộc thông tin train hay đặc trưng mốc 8 trước lúc công bố."),{"kind":"matrix","title":B("Timestamp split and feature availability","Chia theo thời gian và lúc đặc trưng khả dụng"),"caption":B("Origins 1–6 train, 7–8 validation, 9–10 holdout; 11–12 lack a next target. Feature time 8.5 is unavailable at origin 8 and available at 9.","Mốc 1–6 train, 7–8 validation, 9–10 holdout; 11–12 thiếu mục tiêu tới. Đặc trưng lúc 8.5 chưa có tại mốc 8, có tại mốc 9."),"rows":["Origin 7","Origin 8","Feature published 8.5","Origin 9","Origin 10"],"columns":["Split code (train=1,val=2,test=3,none=0)","Available by origin 8 (1/0)"],"values":[[2,1],[2,1],[0,0],[3,0],[3,0]]},
 [B("60 min — Draw the 1–12 origin timeline and place boundaries at 7, 9, and 11 using half-open intervals.","60 phút — Vẽ trục mốc 1–12, đặt ranh giới 7,9,11 theo khoảng nửa mở."),B("60 min — Classify the feature published at 8.5 for decisions at origins 8 and 9; justify each eligibility result.","60 phút — Phân loại đặc trưng công bố 8.5 cho quyết định mốc 8 và 9; giải thích tính hợp lệ."),B("60 min — Implement split_by_timestamp and assert no training label is later than its forecast origin.","60 phút — Cài split_by_timestamp và kiểm tra không nhãn train nào sau mốc dự báo."),B("60 min — Add one overlapping two-step target and specify which origin must be purged to prevent shared-label contamination.","60 phút — Thêm mục tiêu hai bước chồng lấn và nêu mốc cần purge để tránh nhiễm nhãn dùng chung.")],X("w74-d2-split",B("With half-open splits train=[1,6), validation=[6,8), holdout=[8,10), classify origins 5,6,8,10. A feature is published at 7.5; is it eligible at origins 7 and 8?","Với tập nửa mở train=[1,6), validation=[6,8), holdout=[8,10), phân loại mốc 5,6,8,10. Đặc trưng công bố 7.5 có đủ điều kiện tại mốc 7 và 8 không?"),B("The left endpoint is included and the right endpoint excluded. Feature availability requires publication time ≤ decision origin.","Đầu trái được tính, đầu phải không. Đặc trưng chỉ có khi thời điểm công bố ≤ mốc quyết định."),B("Origin 5 is train; 6 and 7 are validation; 8 and 9 are holdout; 10 is outside all listed intervals. Publication at 7.5 is after origin 7, so unavailable there, but before origin 8, so available at 8. This assumes no extra label delay; if labels arrive later, training eligibility must be tightened.","Mốc 5 thuộc train; 6,7 thuộc validation; 8,9 thuộc holdout; 10 ngoài các khoảng. Công bố 7.5 sau mốc 7 nên chưa có, nhưng trước mốc 8 nên có tại 8. Giả định không có trễ nhãn khác; nếu nhãn đến muộn, cần siết điều kiện train."))),
 S(B("74.3 — Freeze metrics, baselines, and tuning","74.3 — Khóa thước đo, đối chứng và tinh chỉnh"),B("A protocol must give the proposed method and each baseline comparable inputs, forecast origins, tuning access, and compute limits. Fix the primary metric and aggregation before outcomes are inspected. If several hyperparameters are searched, record the search space and choose using validation only; the holdout is not another tuning set. Report per-origin results as well as the aggregate to reveal whether a mean hides failures. An honest reproduction can find no gain and still pass the procedural acceptance test.","Quy trình phải cấp cho phương pháp và đối chứng đầu vào, mốc dự báo, quyền tinh chỉnh và giới hạn tính toán tương đương. Khóa thước đo chính và cách gộp trước khi xem kết quả. Nếu tìm nhiều siêu tham số, ghi lưới tìm và chọn chỉ bằng validation; holdout không phải tập tinh chỉnh thứ hai. Báo kết quả từng mốc cùng tổng hợp để thấy trung bình có che lỗi không. Tái lập trung thực có thể không tìm thấy cải thiện mà vẫn đạt kiểm tra quy trình."),B("Freeze two candidates on the same origins [1,2,3]. Primary metric is mean squared loss; validation may choose one of η∈{0.1,0.2}, while the holdout cannot choose. Test losses after selection are method=[1,4,1] and baseline=[2,2,3]. Means are 2 and 7/3≈2.333, so the paired mean difference is −1/3. This sample favors the method but is not proof; the protocol passes only if these exact origins, rules, and outputs are traceable.","Khóa hai ứng viên trên cùng mốc [1,2,3]. Thước đo chính là bình phương sai số trung bình; validation có thể chọn η∈{0.1,0.2}, holdout không được chọn. Tổn thất kiểm tra sau chọn là method=[1,4,1], baseline=[2,2,3]. Trung bình là 2 và 7/3≈2.333, nên sai khác ghép cặp trung bình −1/3. Mẫu này nghiêng về phương pháp nhưng chưa chứng minh; quy trình chỉ đạt nếu truy vết được đúng mốc, quy tắc và đầu ra."),{"kind":"xy","title":B("Matched losses on frozen origins","Tổn thất ghép cặp trên mốc đã khóa"),"caption":B("For origins [1,2,3], method losses [1,4,1] and baseline losses [2,2,3]; means 2 and 2.333, paired mean difference −1/3.","Trên mốc [1,2,3], loss phương pháp [1,4,1], đối chứng [2,2,3]; trung bình 2 và 2.333, sai khác ghép cặp −1/3."),"xLabel":B("Frozen origin","Mốc đã khóa"),"yLabel":B("Squared loss","Bình phương sai số"),"series":[{"name":B("Method","Phương pháp"),"points":[[1,1],[2,4],[3,1]],"mode":"line"},{"name":B("Baseline","Đối chứng"),"points":[[1,2],[2,2],[3,3]],"mode":"line"}]},
 [B("60 min — List the shared origins, primary metric, permitted eta grid, and which split may select eta.","60 phút — Liệt kê mốc chung, thước đo chính, lưới eta được phép và tập nào được chọn eta."),B("60 min — Calculate both means and the three paired differences from the supplied loss vectors.","60 phút — Tính hai trung bình và ba sai khác ghép cặp từ vector tổn thất đã cho."),B("60 min — Implement one shared evaluator and verify that holdout labels are never read during eta selection.","60 phút — Cài bộ đánh giá chung và kiểm tra nhãn holdout không bao giờ được đọc khi chọn eta."),B("60 min — Write acceptance criteria that pass on traceable execution even if the method loses; include a per-origin output table.","60 phút — Viết tiêu chí đạt khi chạy truy vết được dù phương pháp thua; gồm bảng kết quả từng mốc.")],X("w74-d3-metric",B("On shared origins [1,2,3,4], method losses are [3,1,2,4] and baseline losses [2,2,3,3]. Compute each mean and the paired mean difference. If the method has no improvement, does the reproduction protocol necessarily fail?","Trên mốc chung [1,2,3,4], loss phương pháp [3,1,2,4], đối chứng [2,2,3,3]. Tính trung bình và sai khác ghép cặp. Nếu phương pháp không cải thiện, quy trình tái lập nhất thiết thất bại không?"),B("Use the same four rows for both means; define difference as method minus baseline.","Dùng cùng bốn hàng cho hai trung bình; định nghĩa sai khác là phương pháp trừ đối chứng."),B("Method mean=10/4=2.5; baseline mean=10/4=2.5; paired mean difference=0. The methods tie on this fixture, but the protocol does not fail for lacking a positive result. It fails only if the procedure, inputs, or traceability criteria were violated. A zero finding should be reported honestly.","Trung bình phương pháp=10/4=2.5; đối chứng=10/4=2.5; sai khác ghép cặp trung bình=0. Hai phương pháp hòa trên fixture nhưng quy trình không thất bại vì thiếu kết quả dương. Quy trình chỉ thất bại nếu vi phạm cách chạy, đầu vào hoặc truy vết. Cần báo trung thực phát hiện bằng không."))),
 S(B("74.4 — Acceptance tests validate the harness","74.4 — Kiểm thử chấp nhận xác nhận bộ chạy"),B("A deterministic fixture has expected outputs computed independently of the implementation. Compare each actual output against its expected value with declared tolerances and a clear pass/fail rule. Test missing values, boundary timestamps, and a deliberately corrupted row. A fixture mismatch is a software or protocol issue to resolve before interpreting the main experiment; it is not evidence that a research hypothesis is false. Keep the input hash and expected-output file under version control so later changes are visible.","Fixture xác định có đầu ra kỳ vọng tính độc lập với phần triển khai. So từng đầu ra thực tế với kỳ vọng bằng dung sai và quy tắc đạt/trượt đã nêu. Kiểm thử giá trị thiếu, mốc thời gian biên và một hàng cố ý làm sai. Fixture không khớp là vấn đề phần mềm/quy trình cần giải quyết trước khi diễn giải thí nghiệm chính; không phải bằng chứng giả thuyết nghiên cứu sai. Quản lý mã băm đầu vào và tệp đầu ra kỳ vọng theo phiên bản để thấy thay đổi về sau."),B("Five fixtures expect [1,0,1,1,0], where 1 means acceptance pass and 0 means fail. The harness returns [1,0,0,1,0]. Comparing indices gives one mismatch at fixture 3. Therefore harness acceptance fails; do not interpret a research run until the fixture is repaired and all five expected outputs match. One mismatch is sufficient even though four of five values agree.","Năm fixture kỳ vọng [1,0,1,1,0], trong đó 1 là đạt, 0 là trượt. Bộ chạy trả [1,0,0,1,0]. So chỉ số thấy một sai khác ở fixture 3. Vì vậy kiểm thử bộ chạy thất bại; chưa diễn giải thí nghiệm nghiên cứu cho tới khi sửa fixture và cả năm đầu ra khớp. Chỉ một sai khác là đủ dù bốn trên năm giá trị trùng."),{"kind":"matrix","title":B("Expected and actual harness bits","Bit bộ chạy kỳ vọng và thực tế"),"caption":B("Expected [1,0,1,1,0], actual [1,0,0,1,0]; exactly fixture 3 mismatches and acceptance fails.","Kỳ vọng [1,0,1,1,0], thực tế [1,0,0,1,0]; chỉ fixture 3 sai và chấp nhận thất bại."),"rows":["Fixture 1","Fixture 2","Fixture 3","Fixture 4","Fixture 5"],"columns":["Expected","Actual"],"values":[[1,1],[0,0],[1,0],[1,1],[0,0]]},
 [B("60 min — Calculate expected outputs independently and hash the fixture file before running the harness.","60 phút — Tính độc lập đầu ra kỳ vọng và băm tệp fixture trước khi chạy bộ kiểm tra."),B("60 min — Compare the five expected/actual bits and locate every mismatch by index.","60 phút — So năm bit kỳ vọng/thực tế và tìm mọi sai khác theo chỉ số."),B("60 min — Add an assertion that fails on fixture 3; then repair the harness and verify all five bits.","60 phút — Thêm assertion thất bại ở fixture 3; sửa bộ chạy rồi xác nhận đủ năm bit."),B("60 min — Write a short incident note distinguishing harness failure from evidence against the research method.","60 phút — Viết ghi chú phân biệt lỗi bộ chạy với bằng chứng chống lại phương pháp nghiên cứu.")],X("w74-d4-fixture",B("Expected outputs are [2.0,0.0,−1.0,4.0]; actual outputs [2.0,0.1,−1.0,3.0]. With absolute tolerance 0.05, list failures and state whether the experiment is interpretable.","Đầu ra kỳ vọng [2.0,0.0,−1.0,4.0]; thực tế [2.0,0.1,−1.0,3.0]. Với dung sai tuyệt đối 0.05, liệt kê lỗi và cho biết có diễn giải được thí nghiệm không."),B("Take absolute difference at each index and fail when it exceeds 0.05.","Lấy trị tuyệt đối sai khác từng chỉ số và trượt khi vượt 0.05."),B("Differences are [0,0.1,0,1]. Indices 2 and 4 exceed 0.05, so harness acceptance fails at both. The main experiment is not interpretable as protocol-compliant until the cause is fixed and the same frozen fixture is rerun; the mismatch alone does not refute the method.","Sai khác là [0,0.1,0,1]. Chỉ số 2 và 4 vượt 0.05 nên kiểm thử bộ chạy trượt cả hai. Chưa thể diễn giải thí nghiệm chính là tuân thủ quy trình cho tới khi sửa nguyên nhân và chạy lại fixture đã khóa; sai khác riêng nó không bác bỏ phương pháp."))),
 S(B("74.5 — Amendments preserve the audit trail","74.5 — Phụ lục giữ dấu vết kiểm toán"),B("A protocol may need correction, but the original should remain immutable. Record amendment date, old rule, new rule, reason, who made the change, whether outcome data had been seen, and which outputs must be rerun. If the outcome influenced the change, affected analysis is exploratory unless a new untouched holdout is obtained. A versioned record lets a reader distinguish the originally planned test from the corrected one. Transparent deviation is stronger evidence than silently editing a preregistration.","Quy trình có thể cần sửa nhưng bản gốc phải bất biến. Ghi ngày phụ lục, quy tắc cũ/mới, lý do, người sửa, đã xem dữ liệu kết quả chưa và đầu ra nào cần chạy lại. Nếu kết quả ảnh hưởng việc sửa, phân tích liên quan là khám phá trừ khi có holdout mới chưa động tới. Bản ghi có phiên bản giúp người đọc phân biệt phép thử định trước với bản sửa. Sai lệch minh bạch là bằng chứng tốt hơn âm thầm chỉnh đăng ký."),B("At 09:00 the protocol says exclude rows with missing x. At 14:00 the analyst sees that 3 of 20 holdout rows lack x and proposes imputation using the full sample. This is a post-outcome amendment: retain the original exclusion rule, record the new imputation rule and time, mark resulting holdout analysis exploratory, and obtain a new untouched set for confirmatory evaluation. Re-run every downstream table affected by changed features; preserve old output IDs.","Lúc 09:00 quy trình nói loại hàng thiếu x. Lúc 14:00 nhà phân tích thấy 3/20 hàng holdout thiếu x và đề xuất điền bằng toàn mẫu. Đây là phụ lục sau khi xem kết quả: giữ quy tắc loại gốc, ghi quy tắc điền mới và thời điểm, đánh dấu phân tích holdout mới là khám phá, lấy tập mới chưa động tới để xác nhận. Chạy lại mọi bảng phụ thuộc đặc trưng đổi; giữ mã đầu ra cũ."),{"kind":"steps","title":B("An outcome-informed protocol change","Thay quy trình sau khi xem kết quả"),"caption":B("Original 09:00 rule excludes missing x. At 14:00, 3/20 holdout rows are observed missing and a full-sample imputation is proposed; affected results become exploratory.","Quy tắc 09:00 loại x thiếu. Lúc 14:00 đã thấy 3/20 hàng holdout thiếu và đề xuất điền toàn mẫu; kết quả liên quan chuyển sang khám phá."),"steps":[B("Preserve original exclusion protocol","Giữ nguyên quy trình loại ban đầu"),B("Log 14:00 amendment and full-sample imputation","Ghi phụ lục 14:00 và phép điền toàn mẫu"),B("Label affected holdout analysis exploratory","Gắn nhãn khám phá cho phân tích holdout liên quan"),B("Get a new untouched set for confirmation","Lấy tập mới chưa động để xác nhận")]},
 [B("60 min — Create an amendment form with the seven required fields and a checkbox for prior outcome access.","60 phút — Tạo biểu mẫu phụ lục có bảy trường bắt buộc và ô xác nhận đã xem kết quả chưa."),B("60 min — Mark which reports downstream from imputation depend on the changed feature rule.","60 phút — Đánh dấu báo cáo nào phụ thuộc quy tắc đặc trưng đã đổi."),B("60 min — Simulate version IDs v1 and v2; regenerate only affected outputs while retaining v1 artifacts.","60 phút — Mô phỏng mã phiên bản v1,v2; sinh lại đầu ra liên quan nhưng giữ tạo phẩm v1."),B("60 min — Write a reviewer-facing paragraph that admits the deviation and separates exploratory from confirmatory evidence.","60 phút — Viết đoạn cho phản biện thừa nhận sai lệch và tách bằng chứng khám phá khỏi xác nhận.")],X("w74-d5-amend",B("A protocol froze median imputation before any holdout access. The pipeline later finds 2 missing validation values and asks to change to mean imputation before opening the holdout. Is this confirmatory or exploratory? What should be recorded and rerun?","Quy trình khóa điền trung vị trước khi truy cập holdout. Pipeline phát hiện 2 giá trị validation thiếu và đề nghị đổi sang trung bình trước khi mở holdout. Đây là xác nhận hay khám phá? Cần ghi và chạy lại gì?"),B("The timing matters: validation outcomes were available, but holdout outcomes were not. Preserve both protocol versions and check downstream dependencies.","Thời điểm quan trọng: đã có kết quả validation nhưng chưa có holdout. Giữ hai phiên bản quy trình và kiểm tra phụ thuộc phía sau."),B("Because validation outcomes are already observed, the mean-imputation change is outcome-informed and its validation comparison is exploratory. Record old/new rule, date, rationale, exposed outcomes, and affected configs; rerun all validation-dependent preprocessing, baselines, and tables under a new version. The untouched holdout can still provide confirmatory evidence only if the final method and rule are frozen before its single read.","Vì đã thấy kết quả validation, đổi điền trung bình chịu ảnh hưởng kết quả nên so sánh validation là khám phá. Ghi quy tắc cũ/mới, ngày, lý do, kết quả đã xem và cấu hình ảnh hưởng; chạy lại tiền xử lý, đối chứng và bảng phụ thuộc validation dưới phiên bản mới. Holdout chưa động tới vẫn có thể xác nhận nếu khóa phương pháp/quy tắc cuối trước lần đọc duy nhất.")))
 ],{"kind":"flow","title":B("Specify → freeze → test → amend transparently","Đặc tả → khóa → kiểm thử → sửa minh bạch"),"labels":["estimand","chronology","metrics / baselines","fixtures","versioned amendment"],"caption":B("Acceptance is defined before outcomes; later changes retain the old protocol and identify affected exploratory results.","Tiêu chí chấp nhận được định nghĩa trước kết quả; thay đổi về sau giữ quy trình cũ và xác định phân tích khám phá liên quan.")})

W75=M(75,B("Week 75: Turn equations into tested code","Tuần 75: Chuyển phương trình thành mã có kiểm thử"),
 B("A faithful implementation maps every symbol to a variable, shape, unit, and update time. For one online observation, half squared loss is ℓ(w)=½(xᵀw−y)² and gradient is x(xᵀw−y). A step w⁺=w−η∇ℓ uses learning rate η>0; feature scaling changes gradient magnitude. Test exact fits, zero features, shape errors, and a tiny hand-computable case. A shared interface lets method and baseline receive identical origins. Passing unit tests establishes local code behavior, not that an empirical claim or paper result reproduces.",
 "Triển khai trung thành ánh xạ mỗi ký hiệu thành biến, hình dạng, đơn vị và thời điểm cập nhật. Với một quan sát trực tuyến, bình phương sai số nửa là ℓ(w)=½(xᵀw−y)², gradient là x(xᵀw−y). Bước w⁺=w−η∇ℓ dùng tốc độ học η>0; co giãn đặc trưng đổi độ lớn gradient. Kiểm thử khớp chính xác, đặc trưng không, lỗi kích thước và ca nhỏ tính tay được. Giao diện chung giúp phương pháp và đối chứng nhận cùng mốc. Unit test đạt chỉ xác nhận hành vi mã cục bộ, không chứng minh tuyên bố thực nghiệm hay tái lập kết quả bài báo."),
 [B("Derive the scalar chain rule and its vector gradient.","Suy ra quy tắc dây chuyền vô hướng và gradient vector."),B("Check dimensions and compute a complete vector update.","Kiểm tra kích thước và tính đủ một cập nhật vector."),B("Implement guards for exact fits, zero features, and invalid shapes.","Cài kiểm tra khớp chính xác, đặc trưng không và kích thước sai."),B("Use finite differences to diagnose derivative/code mismatches.","Dùng sai phân hữu hạn để chẩn đoán lệch giữa đạo hàm và mã."),B("Separate implementation correctness from experimental validity.","Tách tính đúng mã khỏi tính hợp lệ thực nghiệm.")],
 [
 S(B("75.1 — Derive the scalar gradient","75.1 — Suy ra gradient vô hướng"),B("Let x be a scalar feature, y a fixed target, and θ a scalar weight. Define residual r=xθ−y and loss ℓ(θ)=½r². By the chain rule, dℓ/dθ=½·2r·dr/dθ=r·x=x(xθ−y). Gradient descent subtracts η times this derivative. If the prediction is below y, r<0 and the negative gradient increases θ when x>0. State x's sign before interpreting the update; a negative feature reverses the direction.","Gọi x là đặc trưng vô hướng, y mục tiêu cố định, θ trọng số. Đặt phần dư r=xθ−y và loss ℓ(θ)=½r². Theo quy tắc dây chuyền, dℓ/dθ=½·2r·dr/dθ=r·x=x(xθ−y). Gradient descent trừ η nhân đạo hàm này. Nếu dự báo thấp hơn y, r<0 và gradient âm làm θ tăng khi x>0. Cần nêu dấu x trước khi diễn giải; đặc trưng âm đảo hướng."),B("Use x=2,y=3,θ=1,η=0.1. Prediction is xθ=2, residual r=−1, and loss=½(−1)²=0.5. Gradient=x·r=2·(−1)=−2. Update θ⁺=1−0.1·(−2)=1.2. Prediction after the step is 2.4 and the loss becomes ½(2.4−3)²=0.18, lower than 0.5. This single observation shows the local arithmetic; it does not prove repeated updates converge for arbitrary η or data.","Dùng x=2,y=3,θ=1,η=0.1. Dự báo xθ=2, phần dư r=−1, loss=½(−1)²=0.5. Gradient=x·r=2·(−1)=−2. Cập nhật θ⁺=1−0.1·(−2)=1.2. Dự báo sau bước là 2.4 và loss=½(2.4−3)²=0.18, thấp hơn 0.5. Một quan sát chỉ minh họa số học cục bộ; không chứng minh lặp lại hội tụ với η hoặc dữ liệu bất kỳ."),{"kind":"steps","title":B("One scalar gradient step","Một bước gradient vô hướng"),"caption":B("Inputs x=2,y=3,theta=1,eta=0.1 give prediction 2, residual −1, gradient −2, new theta 1.2, and loss reduction 0.50→0.18.","Đầu vào x=2,y=3,theta=1,eta=0.1 cho dự báo 2, phần dư −1, gradient −2, theta mới 1.2 và loss giảm 0.50→0.18."),"steps":[B("r=xθ−y=2−3=−1","r=xθ−y=2−3=−1"),B("ℓ=½r²=0.5; gradient=xr=−2","ℓ=½r²=0.5; gradient=xr=−2"),B("θ+=θ−η·gradient=1.2","θ+=θ−η·gradient=1.2"),B("New loss=½(2.4−3)²=0.18","Loss mới=½(2.4−3)²=0.18")]},
 [B("60 min — Derive dr/dtheta and dℓ/dtheta symbolically; label where the factor x enters.","60 phút — Suy ra dr/dtheta và dℓ/dtheta bằng ký hiệu; chỉ rõ thừa số x xuất hiện ở đâu."),B("60 min — Substitute x=2,y=3,theta=1,eta=0.1 and compute residual, loss, gradient, and updated loss in order.","60 phút — Thế x=2,y=3,theta=1,eta=0.1; tính lần lượt phần dư, loss, gradient và loss mới."),B("60 min — Implement scalar_step and assert gradient −2, theta_new 1.2, and post-step loss 0.18.","60 phút — Cài scalar_step, kiểm tra gradient −2, theta_new 1.2 và loss sau bước 0.18."),B("60 min — Repeat with x=−2,y=3,theta=1; calculate the gradient sign and explain why the weight update direction changes.","60 phút — Lặp với x=−2,y=3,theta=1; tính dấu gradient và giải thích vì sao hướng cập nhật trọng số đổi.")],X("w75-d1-chain",B("For ℓ(θ)=½(3θ−6)² at θ=1, derive the gradient, take a step with η=0.1, and compute loss before and after.","Với ℓ(θ)=½(3θ−6)² tại θ=1, suy ra gradient, bước η=0.1 và tính loss trước/sau."),B("Set residual r=3θ−6. Then dℓ/dθ=r·3; evaluate it before changing θ.","Đặt phần dư r=3θ−6. Khi đó dℓ/dθ=r·3; tính đạo hàm trước khi đổi θ."),B("At θ=1, r=−3, loss=½·9=4.5 and gradient=3·(−3)=−9. The step gives θ_new=1−0.1·(−9)=1.9. New residual=3·1.9−6=−0.3 and loss=½·0.09=0.045. The reduction is expected because the step moved toward the exact-fit weight 2; a larger step could overshoot.","Tại θ=1, r=−3, loss=½·9=4.5, gradient=3·(−3)=−9. Bước mới θ=1−0.1·(−9)=1.9. Phần dư mới=3·1.9−6=−0.3, loss=½·0.09=0.045. Loss giảm vì bước tiến về trọng số khớp chính xác 2; bước lớn hơn có thể vượt quá."))),
 S(B("75.2 — Vector gradients and shape checks","75.2 — Gradient vector và kiểm tra kích thước"),B("For x∈R^d and w∈R^d, prediction is the dot product xᵀw and residual is scalar r=xᵀw−y. The gradient ∇_wℓ=xr has shape d because a scalar multiplies every feature. The update subtracts a same-shaped vector. A silent row/column broadcast can produce a matrix instead of a weight vector, so assert shapes explicitly. Feature units affect gradient scale, and a single scalar η is meaningful only relative to that scaling.","Với x∈R^d và w∈R^d, dự báo là tích vô hướng xᵀw, phần dư là vô hướng r=xᵀw−y. Gradient ∇_wℓ=xr có kích thước d vì vô hướng nhân từng đặc trưng. Cập nhật trừ vector cùng kích thước. Broadcast hàng/cột âm thầm có thể tạo ma trận thay vì vector trọng số nên phải kiểm hình dạng rõ ràng. Đơn vị đặc trưng ảnh hưởng thang gradient; η vô hướng chỉ có ý nghĩa tương đối với thang đó."),B("Let x=[1,2], w=[1,0.5], y=4. Prediction=1·1+2·0.5=2, residual=−2, loss=½·4=2. Gradient=xr=[−2,−4], shape (2,). With η=0.1, w_new=[1,0.5]−0.1[−2,−4]=[1.2,0.9]. New prediction=1.2+1.8=3, new loss=½(3−4)²=0.5. The vector shape stays (2,) throughout.","Cho x=[1,2], w=[1,0.5], y=4. Dự báo=1·1+2·0.5=2, phần dư=−2, loss=½·4=2. Gradient=xr=[−2,−4], kích thước (2,). Với η=0.1, w_mới=[1,0.5]−0.1[−2,−4]=[1.2,0.9]. Dự báo mới=1.2+1.8=3, loss mới=½(3−4)²=0.5. Kích thước vector luôn là (2)."),{"kind":"steps","title":B("Two-dimensional update with shapes","Cập nhật hai chiều và kích thước"),"caption":B("x=[1,2], w=[1,0.5], y=4, eta=0.1: prediction=2, gradient=[−2,−4], w_new=[1.2,0.9], loss 2→0.5. All vectors have shape (2,).","x=[1,2], w=[1,0.5], y=4, eta=0.1: dự báo=2, gradient=[−2,−4], w_mới=[1.2,0.9], loss 2→0.5. Mọi vector có kích thước (2)."),"steps":[B("xᵀw=2; residual=2−4=−2","xᵀw=2; phần dư=2−4=−2"),B("Gradient x·residual=[−2,−4]","Gradient x·phần dư=[−2,−4]"),B("Update w=[1,0.5]+[0.2,0.4]=[1.2,0.9]","Cập nhật w=[1,0.5]+[0.2,0.4]=[1.2,0.9]"),B("New prediction 3; half squared loss=0.5","Dự báo mới 3; nửa bình phương sai số=0.5")]},
 [B("60 min — Annotate dimensions of x, w, xᵀw, residual, gradient, and update before calculating.","60 phút — Ghi kích thước x,w,xᵀw, phần dư, gradient và bước cập nhật trước khi tính."),B("Compute the exact vector example and verify both coordinates of the gradient separately.","Tính ví dụ vector chính xác và kiểm tra riêng hai tọa độ gradient."),B("Implement a vectorized step that rejects x/w length mismatch; assert all intermediate arrays retain shape (2,).","Cài bước vector từ chối x/w lệch chiều; xác nhận mọi mảng trung gian giữ kích thước (2)."),B("Intentionally pass x as shape (1,2) and w as (2,1); catch the broadcasted output before it enters training.","Cố ý truyền x kích thước (1,2) và w kích thước (2,1); bắt đầu ra broadcast trước khi vào huấn luyện.")],X("w75-d2-vector",B("Use x=[2,−1], w=[0.5,1], y=2 and eta=0.2. Compute prediction, residual, gradient shape/value, updated weights, and new loss.","Dùng x=[2,−1], w=[0.5,1], y=2, eta=0.2. Tính dự báo, phần dư, kích thước/giá trị gradient, trọng số mới và loss mới."),B("Dot x and w first. Multiply each feature by the scalar residual; then subtract eta times that vector.","Tính tích vô hướng trước. Nhân từng đặc trưng với phần dư vô hướng rồi trừ eta nhân vector đó."),B("Prediction=2·0.5−1·1=0, residual=−2, loss=½·4=2. Gradient=[2,−1]·(−2)=[−4,2], shape (2,). Updated w=[0.5,1]−0.2[−4,2]=[1.3,0.6]. New prediction=2.6−0.6=2, so new loss=0. The exact fit is reached in this particular step; that does not imply the same eta is stable for every x.","Dự báo=2·0.5−1·1=0, phần dư=−2, loss=½·4=2. Gradient=[2,−1]·(−2)=[−4,2], kích thước (2). w mới=[0.5,1]−0.2[−4,2]=[1.3,0.6]. Dự báo mới=2.6−0.6=2, nên loss mới=0. Bước cụ thể này đạt khớp chính xác; không có nghĩa eta đó ổn định với mọi x."))),
 S(B("75.3 — Test invariants before scaling","75.3 — Kiểm thử bất biến trước khi mở rộng"),B("Unit tests should target mathematical invariants, not just one expected output. At exact fit xᵀw=y, residual and gradient must be zero. If x=0, changing w cannot change the prediction and the gradient is zero. A mismatched feature dimension should raise an error rather than broadcast. Test the loss is nonnegative and confirm a sufficiently small descent step reduces it in a hand-checkable case. These checks catch sign and shape defects but cannot detect data leakage or a misspecified study protocol.","Unit test nên nhắm bất biến toán học, không chỉ một đầu ra kỳ vọng. Khi khớp chính xác xᵀw=y, phần dư và gradient phải bằng không. Nếu x=0, đổi w không đổi dự báo và gradient bằng không. Lệch chiều đặc trưng phải báo lỗi thay vì broadcast. Kiểm tra loss không âm và một bước giảm đủ nhỏ làm loss giảm trong ca tính tay. Các kiểm tra này bắt lỗi dấu/kích thước nhưng không phát hiện rò rỉ dữ liệu hay quy trình nghiên cứu sai."),B("Use x=[2,−1], w=[1,2], y=0. Then xᵀw=2−2=0, so residual=0, loss=0, and gradient=[0,0]. Change y to 1: residual=−1, loss=0.5 and gradient=[−2,1]. With eta=0.1, w_new=[1.2,1.9], prediction=2.4−1.9=0.5 and new loss=½(0.5−1)²=0.125. The exact-fit test and descent test exercise different invariants.","Dùng x=[2,−1], w=[1,2], y=0. Khi đó xᵀw=2−2=0, phần dư=0, loss=0 và gradient=[0,0]. Đổi y thành 1: phần dư=−1, loss=0.5, gradient=[−2,1]. Với eta=0.1, w_mới=[1.2,1.9], dự báo=2.4−1.9=0.5, loss mới=½(0.5−1)²=0.125. Kiểm tra khớp chính xác và giảm loss là hai bất biến khác nhau."),{"kind":"steps","title":B("Exact-fit and descent invariants","Bất biến khớp chính xác và giảm loss"),"caption":B("At x=[2,−1],w=[1,2],y=0 the exact-fit gradient is [0,0]. Changing y to 1 and stepping eta=0.1 gives loss 0.5→0.125.","Với x=[2,−1],w=[1,2],y=0, gradient khi khớp là [0,0]. Đổi y=1, bước eta=0.1 cho loss 0.5→0.125."),"steps":[B("Exact fit: prediction 0, target 0, residual=gradient=0","Khớp: dự báo 0, mục tiêu 0, phần dư=gradient=0"),B("Perturbed target y=1: residual −1, loss 0.5","Mục tiêu y=1: phần dư −1, loss 0.5"),B("Gradient [−2,1] updates weights to [1.2,1.9]","Gradient [−2,1] cập nhật trọng số thành [1.2,1.9]"),B("New prediction 0.5; loss=0.125","Dự báo mới 0.5; loss=0.125")]},
 [B("60 min — Prove the exact-fit and zero-feature gradients from the formula, without calling the implementation.","60 phút — Chứng minh gradient khớp chính xác và đặc trưng không từ công thức, không gọi mã."),B("Calculate the two cases in the example; explain why they test separate failure modes.","Tính hai trường hợp trong ví dụ; giải thích vì sao chúng kiểm hai lỗi khác nhau."),B("Write tests for exact fit, x=0, negative x, shape mismatch, and nonnegative loss.","Viết kiểm thử khớp, x=0, x âm, lệch kích thước và loss không âm."),B("Introduce a sign bug by adding eta*gradient; show which test fails and retain the failing trace as evidence.","Cố ý lỗi dấu bằng cách cộng eta*gradient; chỉ ra kiểm thử nào trượt và lưu log thất bại.")],X("w75-d3-invariants",B("With x=0, w=[4,−2], y=3, what are prediction, loss, and gradient? Then give a two-dimensional shape error that the API should reject.","Với x=0, w=[4,−2], y=3, dự báo, loss, gradient là gì? Nêu lỗi kích thước hai chiều mà API cần từ chối."),B("A zero feature vector has zero dot product and multiplies the scalar residual in the gradient.","Vector đặc trưng không có tích vô hướng bằng 0 và nhân phần dư vô hướng trong gradient."),B("Prediction=0, residual=−3, loss=½·9=4.5, and gradient=0·(−3)=[0,0]. Changing w cannot affect this prediction. The API should reject, for example, x shape (2,) with w shape (3,), because their dot product is undefined; it must not broadcast them into a matrix.","Dự báo=0, phần dư=−3, loss=½·9=4.5, gradient=0·(−3)=[0,0]. Đổi w không ảnh hưởng dự báo. API phải từ chối, ví dụ x kích thước (2,) và w (3,), vì tích vô hướng không xác định; không broadcast thành ma trận."))),
 S(B("75.4 — Finite differences are a diagnostic","75.4 — Sai phân hữu hạn là phép chẩn đoán"),B("An analytic gradient can be checked numerically with a central difference D_h=[ℓ(θ+h)−ℓ(θ−h)]/(2h). For a smooth function its truncation error is typically order h², while floating-point cancellation grows when h is too small. Therefore test several h values and a relative tolerance; one finite-difference result is not proof of correctness. For vector parameters, perturb one coordinate at a time and compare each component. A mismatch can reveal a derivative sign error, wrong reduction, or stale parameter value.","Có thể kiểm tra gradient giải tích bằng sai phân trung tâm D_h=[ℓ(θ+h)−ℓ(θ−h)]/(2h). Với hàm trơn, sai số cắt thường bậc h², còn triệt tiêu số thực tăng khi h quá nhỏ. Vì vậy thử nhiều h và dung sai tương đối; một kết quả sai phân không chứng minh mã đúng. Với tham số vector, nhiễu từng tọa độ và so từng thành phần. Sai lệch có thể phát hiện lỗi dấu đạo hàm, phép gộp hay tham số cũ."),B("For ℓ(θ)=½(2θ−3)² at θ=1, analytic gradient is 2(2−3)=−2. With h=0.001, ℓ(1.001)=½(−0.998)²=0.498002 and ℓ(0.999)=½(−1.002)²=0.502002. Central difference=(0.498002−0.502002)/0.002=−2. The quadratic makes this particular central difference exact up to arithmetic rounding; a nonlinear loss would generally retain truncation error.","Với ℓ(θ)=½(2θ−3)² tại θ=1, gradient giải tích là 2(2−3)=−2. Với h=0.001, ℓ(1.001)=½(−0.998)²=0.498002 và ℓ(0.999)=½(−1.002)²=0.502002. Sai phân trung tâm=(0.498002−0.502002)/0.002=−2. Với hàm bậc hai này, sai phân trung tâm chính xác ngoài làm tròn số; hàm phi tuyến thường có sai số cắt."),{"kind":"xy","title":B("Central difference across step sizes","Sai phân trung tâm theo kích thước bước"),"caption":B("At theta=1 the analytic derivative is −2. For this quadratic, central differences at h=0.1,0.01,0.001 are all −2 in exact arithmetic; floating-point error may appear for extremely small h.","Tại theta=1 đạo hàm giải tích bằng −2. Với hàm bậc hai này, sai phân trung tâm h=0.1,0.01,0.001 đều bằng −2 trong số học chính xác; lỗi dấu phẩy động có thể xuất hiện nếu h cực nhỏ."),"xLabel":B("Step size h","Kích thước bước h"),"yLabel":B("Derivative estimate","Ước lượng đạo hàm"),"series":[{"name":B("Central difference","Sai phân trung tâm"),"points":[[0.1,-2],[0.01,-2],[0.001,-2]],"mode":"scatter"},{"name":B("Analytic value","Giá trị giải tích"),"points":[[0.001,-2],[0.1,-2]],"mode":"line"}]},
 [B("60 min — Derive the central-difference formula and predict its behavior for a quadratic.","60 phút — Suy ra công thức sai phân trung tâm và dự đoán hành vi với hàm bậc hai."),B("60 min — Evaluate the two perturbed losses for h=0.001 and reproduce derivative −2.","60 phút — Tính hai loss nhiễu với h=0.001 và tái tạo đạo hàm −2."),B("60 min — Compare analytic and numeric gradients at h={1e−1,1e−3,1e−6}; report absolute and relative errors.","60 phút — So gradient giải tích/số với h={1e−1,1e−3,1e−6}; báo sai số tuyệt đối và tương đối."),B("60 min — Add one cubic term to the loss, sweep h, and explain the region where truncation gives way to floating-point cancellation.","60 phút — Thêm hạng bậc ba vào loss, quét h và giải thích miền sai số cắt chuyển sang triệt tiêu dấu phẩy động.")],X("w75-d4-finite",B("For ℓ(θ)=½(θ−2)² at θ=0.5, compare analytic gradient with central difference for h=0.1. Show both perturbed losses and the estimate.","Với ℓ(θ)=½(θ−2)² tại θ=0.5, so đạo hàm giải tích với sai phân trung tâm h=0.1. Trình bày hai loss nhiễu và ước lượng."),B("Analytic derivative is θ−2. Evaluate loss at 0.6 and 0.4, then divide their difference by 0.2.","Đạo hàm giải tích là θ−2. Tính loss tại 0.6 và 0.4 rồi chia hiệu cho 0.2."),B("Analytic gradient=0.5−2=−1.5. ℓ(0.6)=½(−1.4)²=0.98; ℓ(0.4)=½(−1.6)²=1.28. Central difference=(0.98−1.28)/(0.2)=−1.5, matching the exact derivative because the loss is quadratic. This test checks the numerical routine at this point, not every function or parameter shape.","Gradient giải tích=0.5−2=−1.5. ℓ(0.6)=½(−1.4)²=0.98; ℓ(0.4)=½(−1.6)²=1.28. Sai phân trung tâm=(0.98−1.28)/(0.2)=−1.5, khớp đạo hàm chính xác vì loss bậc hai. Kiểm tra này xác nhận routine tại điểm này, không phải mọi hàm hay kích thước tham số."))),
 S(B("75.5 — Passing tests is not a reproduced claim","75.5 — Unit test đạt không đồng nghĩa tái lập tuyên bố"),B("Correctly computing one update establishes an implementation property on tested inputs. A reproduction claim additionally needs a faithful objective, correct data provenance, predeclared chronology, matched comparator, valid metric, and traceable run. A program can pass gradient tests and still use a future feature or evaluate on the wrong split. Keep unit tests, integration tests, and empirical results in separate evidence sections. Report exactly which level passed and which remains untested.","Tính đúng một bước cập nhật xác nhận thuộc tính triển khai trên đầu vào đã kiểm. Tuyên bố tái lập còn cần mục tiêu trung thành, nguồn dữ liệu đúng, trình tự định trước, đối chứng cân bằng, thước đo hợp lệ và lần chạy truy vết được. Mã có thể qua kiểm thử gradient nhưng vẫn dùng đặc trưng tương lai hoặc chia tập sai. Giữ unit test, integration test và kết quả thực nghiệm ở các phần bằng chứng riêng. Báo chính xác tầng nào đạt và tầng nào chưa kiểm."),B("The implementation passes 4/4 scalar fixtures and 8/8 vector gradient checks. However, the evaluation table includes a feature published at origin 12 in a forecast issued at origin 10. Code correctness is supported for those update tests, but the empirical reproduction is invalid because chronology fails. Exclude or lag the feature, version the correction, rerun affected origins, and label the old comparison superseded; do not describe the unit-test pass as evidence for the paper's performance claim.","Triển khai đạt 4/4 fixture vô hướng và 8/8 kiểm gradient vector. Tuy nhiên bảng đánh giá dùng đặc trưng công bố ở mốc 12 trong dự báo phát tại mốc 10. Tính đúng mã được hỗ trợ ở các kiểm thử cập nhật, nhưng tái lập thực nghiệm không hợp lệ vì sai thời gian. Loại hoặc trễ đặc trưng, phiên bản hóa sửa đổi, chạy lại mốc ảnh hưởng và ghi so sánh cũ là bị thay; không gọi unit test là bằng chứng cho tuyên bố hiệu năng của bài."),{"kind":"matrix","title":B("Two evidence layers","Hai tầng bằng chứng"),"caption":B("Update tests pass 4/4 scalar and 8/8 vector cases; empirical chronology fails because a feature published at 12 was used at forecast origin 10.","Kiểm thử cập nhật đạt 4/4 ca vô hướng và 8/8 vector; thời gian thực nghiệm trượt vì dùng đặc trưng công bố ở 12 cho dự báo mốc 10."),"rows":["Scalar unit tests","Vector gradient tests","Origin-10 data check","Overall reproduction"],"columns":["Pass (1) / valid","Fail (0) / invalid"],"values":[[1,0],[1,0],[0,1],[0,1]]},
 [B("60 min — Classify each supplied fact as unit-test, integration, chronology, or empirical-claim evidence.","60 phút — Phân loại từng dữ kiện vào bằng chứng unit test, tích hợp, thời gian hay tuyên bố thực nghiệm."),B("60 min — Locate the feature publication/origin mismatch and write the earliest eligible origin.","60 phút — Tìm sai khác thời điểm công bố/mốc dự báo và ghi mốc sớm nhất đủ điều kiện."),B("60 min — Add a point-in-time assertion that blocks publication_time>origin; retain the 12 passing unit checks separately.","60 phút — Thêm assertion thời điểm chặn publication_time>origin; giữ riêng 12 unit test đạt."),B("60 min — Write a release note that states what passed, what failed, and which conclusions are withdrawn pending rerun.","60 phút — Viết ghi chú phát hành nêu mục đạt, trượt và kết luận nào rút lại chờ chạy lại.")],X("w75-d5-evidence",B("All derivative tests pass, but the benchmark used labels published after their forecast origins. What can you conclude about code correctness and the reported benchmark? Name the repair and evidence to retain.","Mọi kiểm thử đạo hàm đều đạt nhưng benchmark dùng nhãn công bố sau mốc dự báo. Kết luận gì về tính đúng mã và benchmark đã báo? Nêu cách sửa và bằng chứng cần giữ."),B("Tests establish only the behavior they exercise. Compare every label's publication time with its decision origin.","Kiểm thử chỉ xác nhận hành vi được chạy. So thời điểm công bố từng nhãn với mốc quyết định."),B("Conclude that tested derivative code matches its fixtures; do not conclude the benchmark is valid. Lag/exclude future labels, version the correction, rerun all affected outputs, and preserve old results as superseded with their configuration and reason. Reassess the empirical claim only after the point-in-time audit passes.","Kết luận mã đạo hàm khớp fixture đã thử; không kết luận benchmark hợp lệ. Trễ/loại nhãn tương lai, phiên bản hóa sửa đổi, chạy lại mọi đầu ra liên quan và giữ kết quả cũ là bị thay cùng cấu hình/lý do. Chỉ đánh giá lại tuyên bố thực nghiệm sau khi kiểm thời điểm đạt.")))
 ],{"kind":"flow","title":B("Equation → implementation → checks → evidence","Phương trình → triển khai → kiểm thử → bằng chứng"),"labels":["symbols / shapes","derived gradient","tested update","data timing","claim boundary"],"caption":B("Unit correctness is necessary, while valid empirical evidence additionally requires chronology and protocol.","Mã đúng là cần thiết, nhưng bằng chứng thực nghiệm hợp lệ còn cần thời gian và quy trình đúng.")})

W76=M(76,B("Week 76: Evaluate reproductions chronologically","Tuần 76: Đánh giá tái lập theo thời gian"),
 B("A time-series reproduction must replay the decision process at each origin: fit on eligible past data, issue a forecast, reveal the target, then advance. Expanding and rolling windows answer different questions because their training sets differ. When target windows overlap, loss rows share outcomes and are dependent; the number of origins is not the number of independent replications. Compare to a published baseline and simple alternatives with matched information, tuning, and compute. Preserve failed runs. A reproduction asks whether the specified procedure yields compatible evidence, not whether every digit is identical.","Tái lập chuỗi thời gian phải phát lại quá trình quyết định ở từng mốc: khớp trên quá khứ đủ điều kiện, phát dự báo, mở mục tiêu rồi tiến tiếp. Cửa sổ mở rộng và trượt trả lời câu hỏi khác nhau vì tập huấn luyện khác. Khi cửa sổ mục tiêu chồng lấn, hàng loss dùng chung kết quả nên phụ thuộc; số mốc không bằng số lần lặp độc lập. So với đối chứng công bố và lựa chọn đơn giản bằng thông tin, tinh chỉnh, tính toán tương đương. Giữ lần chạy lỗi. Tái lập hỏi quy trình quy định có cho bằng chứng tương thích không, không đòi từng chữ số giống hệt."),
 [B("Replay an expanding-window forecast without future labels.","Phát lại dự báo cửa sổ mở rộng không dùng nhãn tương lai."),B("Derive dependence created by overlapping targets.","Suy ra phụ thuộc do mục tiêu chồng lấn."),B("Distinguish fixed-fit and repeated-refit estimands.","Phân biệt đại lượng khớp cố định và khớp lại."),B("Aggregate by declared blocks and retain per-origin values.","Gộp theo khối định trước và giữ giá trị từng mốc."),B("Interpret numerical compatibility without demanding identical digits.","Diễn giải tương thích số mà không đòi từng chữ số giống nhau.")],
 [
 S(B("76.1 — Walk forward one origin at a time","76.1 — Tiến từng mốc một"),B("At origin t, an expanding-window mean predictor uses y₁,…,y_{t−1} and forecasts their mean. After the next target is revealed, it may refit for the next origin. This differs from fitting once and freezing coefficients. Logging the cutoff makes chronology auditable. A test split should be a contiguous future segment when the intended deployment is forward prediction; random folds answer another question. Report both the per-origin errors and the aggregation so a large miss is not hidden by an average.","Tại mốc t, bộ dự báo trung bình cửa sổ mở rộng dùng y₁,…,y_{t−1} để dự báo trung bình của chúng. Sau khi mở mục tiêu kế tiếp, nó có thể khớp lại cho mốc sau. Cách này khác khớp một lần rồi giữ hệ số. Ghi mốc cắt giúp kiểm toán thời gian. Tập kiểm tra nên là đoạn tương lai liên tục nếu mục tiêu triển khai là dự báo tiến; chia ngẫu nhiên trả lời câu hỏi khác. Báo cả sai số từng mốc và cách gộp để một lần trượt lớn không bị trung bình che."),B("For targets [2,4,6,8,10], forecast origins 2–5 using the mean of the prefix. Predictions are [2,3,4,5]; errors target−forecast are [2,3,4,5], squared losses [4,9,16,25], total 54 and mean 13.5. At origin 5, value 10 is not in the training prefix. The rising level makes this simple expanding mean lag; that is a result of the toy sequence, not a reason to change the protocol after observing it.","Với mục tiêu [2,4,6,8,10], dự báo mốc 2–5 bằng trung bình tiền tố. Dự báo [2,3,4,5]; sai số mục tiêu−dự báo [2,3,4,5], bình phương [4,9,16,25], tổng 54, trung bình 13.5. Tại mốc 5, giá trị 10 chưa nằm trong tiền tố huấn luyện. Mức tăng làm trung bình mở rộng bị trễ; đó là kết quả chuỗi đồ chơi, không phải lý do sửa quy trình sau khi xem."),{"kind":"xy","title":B("Expanding-mean forecasts","Dự báo trung bình mở rộng"),"caption":B("Targets [2,4,6,8,10]; forecasts at origins 2–5 are [2,3,4,5], each computed from the strictly earlier prefix. Origin 1 initializes the prefix.","Mục tiêu [2,4,6,8,10]; dự báo mốc 2–5 là [2,3,4,5], mỗi dự báo tính từ tiền tố trước đó. Mốc 1 khởi tạo tiền tố."),"xLabel":B("Forecast origin","Mốc dự báo"),"yLabel":B("Target units","Đơn vị mục tiêu"),"series":[{"name":B("Observed target","Mục tiêu quan sát"),"points":[[1,2],[2,4],[3,6],[4,8],[5,10]],"mode":"line"},{"name":B("Forecast","Dự báo"),"points":[[2,2],[3,3],[4,4],[5,5]],"mode":"line"}]},[B("60 min — For each origin 2–5, write the exact prefix available before the target is revealed.","60 phút — Với từng mốc 2–5, ghi tiền tố chính xác có trước khi mở mục tiêu."),B("60 min — Recompute prefix means and four squared losses; preserve the per-origin vector [4,9,16,25].","60 phút — Tính lại trung bình tiền tố và bốn bình phương sai số; giữ vector từng mốc [4,9,16,25]."),B("60 min — Implement an expanding-window loop with an assertion that max(training_index)<origin.","60 phút — Cài vòng lặp mở rộng và assertion max(training_index)<origin."),B("60 min — Add an intentionally shuffled split and show which future value leaks into an earlier forecast.","60 phút — Thêm cách chia xáo trộn có chủ ý và chỉ ra giá trị tương lai nào rò vào dự báo trước.")],X("w76-d1-walk",B("Targets are [3,5,4,8]. At origins 2–4, forecast each target using the mean of all earlier targets. Compute predictions and squared losses.","Mục tiêu [3,5,4,8]. Tại mốc 2–4, dự báo bằng trung bình mọi mục tiêu trước. Tính dự báo và bình phương sai số."),B("Origin 2 uses [3], origin 3 uses [3,5], and origin 4 uses [3,5,4].","Mốc 2 dùng [3], mốc 3 dùng [3,5], mốc 4 dùng [3,5,4]."),B("Predictions are [3,4,4]. Squared losses are (5−3)²=4, (4−4)²=0, and (8−4)²=16; total=20. Each prediction uses only earlier targets, so this is a valid expanding-prefix calculation.","Dự báo [3,4,4]. Bình phương sai số là (5−3)²=4, (4−4)²=0 và (8−4)²=16; tổng=20. Mỗi dự báo chỉ dùng mục tiêu trước nên phép tính tiền tố mở rộng hợp lệ."))),
 S(B("76.2 — Overlapping targets are dependent","76.2 — Mục tiêu chồng lấn tạo phụ thuộc"),B("If daily innovations r_t are independent with variance σ², adjacent two-step sums u_t=r_t+r_{t+1} and u_{t+1}=r_{t+1}+r_{t+2} share r_{t+1}. Their covariance is Var(r_{t+1})=σ², while each variance is 2σ², so correlation is 1/2. Treating these overlapping windows as independent understates uncertainty. The arithmetic assumes independent equal-variance innovations; real dependence may be stronger or weaker. Use non-overlapping blocks or an uncertainty method that preserves serial structure, and state block length.","Nếu đổi mới ngày r_t độc lập, phương sai σ², tổng hai bước liền kề u_t=r_t+r_{t+1} và u_{t+1}=r_{t+1}+r_{t+2} dùng chung r_{t+1}. Hiệp phương sai là Var(r_{t+1})=σ², mỗi phương sai là 2σ², nên tương quan 1/2. Xem cửa sổ chồng lấn là độc lập sẽ đánh giá thấp bất định. Phép tính giả định đổi mới độc lập cùng phương sai; phụ thuộc thật có thể mạnh/yếu hơn. Dùng khối không chồng lấn hoặc phương pháp bất định giữ cấu trúc chuỗi và nêu độ dài khối."),B("Let independent returns r₁=1,r₂=−1,r₃=2,r₄=1. Two-step targets are u₁=r₁+r₂=0, u₂=r₂+r₃=1, u₃=r₃+r₄=3. Adjacent pairs (u₁,u₂) share r₂; (u₂,u₃) share r₃. This visible overlap explains dependence even though the underlying r values were stipulated independent. Three windows are not three independent replications.","Cho lợi suất độc lập r₁=1,r₂=−1,r₃=2,r₄=1. Mục tiêu hai bước là u₁=r₁+r₂=0, u₂=r₂+r₃=1, u₃=r₃+r₄=3. Cặp kề (u₁,u₂) dùng chung r₂; (u₂,u₃) dùng chung r₃. Phần chồng lấn trực tiếp giải thích phụ thuộc dù r được giả định độc lập. Ba cửa sổ không phải ba lần lặp độc lập."),{"kind":"matrix","title":B("Returns reused by overlapping targets","Lợi suất dùng lại trong mục tiêu chồng lấn"),"caption":B("Returns [1,−1,2,1] create two-step targets u1=0,u2=1,u3=3. Adjacent target rows share one return.","Lợi suất [1,−1,2,1] tạo mục tiêu hai bước u1=0,u2=1,u3=3. Hai hàng mục tiêu kề nhau dùng chung một lợi suất."),"rows":["u1","u2","u3"],"columns":["First return","Second return","Target sum"],"values":[[1,-1,0],[-1,2,1],[2,1,3]]},[B("60 min — Expand u1,u2,u3 in terms of r and circle each return that appears twice.","60 phút — Khai triển u1,u2,u3 theo r và khoanh lợi suất xuất hiện hai lần."),B("60 min — Derive Cov(u1,u2)=σ² and Var(u)=2σ² under the stated independent equal-variance assumption.","60 phút — Suy ra Cov(u1,u2)=σ² và Var(u)=2σ² dưới giả định độc lập cùng phương sai."),B("60 min — Code a target-window index map and assert exactly one shared return between adjacent two-step windows.","60 phút — Cài ánh xạ chỉ số cửa sổ và kiểm tra đúng một lợi suất chung giữa hai cửa sổ hai bước kề."),B("60 min — Compare a naive standard error treating 3 targets independent with a block summary; state why neither is precise with three rows.","60 phút — So sai số chuẩn ngây thơ coi 3 mục tiêu độc lập với tóm tắt theo khối; nêu vì sao cả hai chưa chính xác với ba hàng.")],X("w76-d2-overlap",B("Let independent r have variance 4. Define u_t=r_t+r_{t+1}. Compute Var(u_t), Cov(u_t,u_{t+1}), and their correlation. What error results from calling adjacent targets independent?","Cho r độc lập phương sai 4. Đặt u_t=r_t+r_{t+1}. Tính Var(u_t), Cov(u_t,u_{t+1}) và tương quan. Sai gì khi gọi mục tiêu kề độc lập?"),B("Each target has two independent terms; adjacent targets share exactly one term.","Mỗi mục tiêu có hai hạng độc lập; hai mục tiêu kề dùng chung đúng một hạng."),B("Var(u_t)=4+4=8. Cov(u_t,u_{t+1})=Var(shared r_{t+1})=4. Correlation=4/√(8·8)=0.5. Treating them as independent ignores positive covariance and generally understates uncertainty in an average; the calculation relies on the stated iid-variance structure.","Var(u_t)=4+4=8. Cov(u_t,u_{t+1})=Var(r_{t+1} chung)=4. Tương quan=4/√(8·8)=0.5. Coi chúng độc lập bỏ qua hiệp phương sai dương và thường đánh giá thấp bất định trung bình; phép tính dựa vào cấu trúc cùng phương sai độc lập đã nêu."))),
 S(B("76.3 — Refitting changes the estimand","76.3 — Khớp lại làm đổi đại lượng"),B("A fixed-fit evaluation estimates performance of one parameter vector trained at a cutoff. An expanding refit estimates performance of a learning procedure that repeatedly updates with newly revealed data. Both can be valid, but they are not interchangeable. To compare them, specify whether the estimand is a frozen model or an adaptive policy. Reusing the same evaluation labels to choose refit frequency adds another tuning degree of freedom. Report when parameters change and exactly which past rows each fit sees.","Đánh giá khớp cố định ước lượng hiệu năng của một vector tham số huấn luyện tại mốc cắt. Khớp mở rộng ước lượng quy trình học được cập nhật nhiều lần khi nhãn mới xuất hiện. Cả hai đều có thể hợp lệ nhưng không thay thế nhau. Khi so sánh, nêu đại lượng là mô hình cố định hay chính sách thích nghi. Dùng lại nhãn đánh giá để chọn tần suất khớp lại thêm bậc tự do tinh chỉnh. Báo lúc tham số đổi và hàng quá khứ mỗi lần khớp được dùng."),B("For targets [1,3,5,7], freeze the origin-2 mean 1 for later forecasts: predictions at origins 3–4 are [1,1], losses [16,36], mean 26. Under the declared expanding policy, refit before each forecast: means [2,3], losses [9,16], mean 12.5. The second number evaluates the update procedure, not the frozen estimate. It is not fair to call 12.5 the same estimand as 26; both use the same two targets but different training rules.","Với mục tiêu [1,3,5,7], khóa trung bình mốc 2 bằng 1 để dự báo sau: dự báo mốc 3–4 là [1,1], loss [16,36], trung bình 26. Theo chính sách mở rộng đã nêu, khớp lại trước mỗi dự báo: trung bình [2,3], loss [9,16], trung bình 12.5. Số thứ hai đánh giá quy trình cập nhật, không phải ước lượng cố định. Không thể gọi 12.5 cùng đại lượng với 26; dù cùng hai mục tiêu nhưng quy tắc huấn luyện khác."),{"kind":"bars","title":B("Frozen fit versus expanding refit","Khớp cố định so với khớp mở rộng"),"caption":B("On targets 5 and 7, the frozen mean=1 gives mean squared loss 26; the expanding refit gives forecasts [2,3] and mean loss 12.5. These evaluate different procedures.","Trên mục tiêu 5 và 7, trung bình cố định=1 cho bình phương loss trung bình 26; khớp mở rộng dự báo [2,3], loss trung bình 12.5. Đây là hai quy trình khác nhau."),"xLabel":B("Evaluation rule","Quy tắc đánh giá"),"yLabel":B("Mean squared loss","Bình phương loss trung bình"),"values":[{"label":B("Frozen","Cố định"),"value":26},{"label":B("Expanding refit","Khớp mở rộng"),"value":12.5}]},[B("60 min — Write the training information set for the frozen fit and for each expanding refit.","60 phút — Viết tập thông tin huấn luyện của mô hình cố định và từng lần khớp mở rộng."),B("60 min — Reproduce predictions/losses [1,1]/[16,36] and [2,3]/[9,16] from the same targets.","60 phút — Tái tạo dự báo/loss [1,1]/[16,36] và [2,3]/[9,16] trên cùng mục tiêu."),B("60 min — Code frozen_model and expanding_policy as separate functions; assert their evaluation labels differ.","60 phút — Cài frozen_model và expanding_policy thành hàm riêng; kiểm tra nhãn đại lượng đánh giá khác nhau."),B("60 min — Draft a report sentence naming the rule, refit timing, and why the two means cannot be compared as if identical estimands.","60 phút — Soạn câu báo cáo nêu quy tắc, lúc khớp lại và vì sao không so hai trung bình như cùng đại lượng.")],X("w76-d3-estimand",B("Targets are [2,4,8]. Freeze a model at origin 1 with forecast 2 for both later outcomes. Separately use the expanding mean. Compute each method's two test losses and state which estimates a fixed model versus a refitting procedure.","Mục tiêu [2,4,8]. Khóa mô hình ở mốc 1 dự báo 2 cho hai kết quả sau. Riêng trung bình mở rộng được khớp lại. Tính hai loss và nêu phép nào đánh giá mô hình cố định/quy trình khớp lại."),B("The frozen forecast stays 2. The expanding means before origins 2 and 3 use [2] and [2,4].","Dự báo cố định luôn là 2. Trung bình mở rộng trước mốc 2,3 dùng [2] và [2,4]."),B("Frozen predictions [2,2] have losses 4 and 36, mean 20. Expanding predictions [2,3] have losses 4 and 25, mean 14.5. The first estimates a single frozen fit; the second estimates a refitting policy. They share test targets but answer different questions.","Dự báo cố định [2,2] có loss 4 và 36, trung bình 20. Dự báo mở rộng [2,3] có loss 4 và 25, trung bình 14.5. Phép đầu đánh giá một mô hình cố định; phép sau đánh giá chính sách khớp lại. Chúng dùng chung mục tiêu kiểm tra nhưng trả lời câu hỏi khác."))),
 S(B("76.4 — Aggregate without hiding time structure","76.4 — Gộp mà không che cấu trúc thời gian"),B("An overall mean can hide a regime where the method fails. Preserve chronological per-origin differences, then summarize by blocks defined before analysis. Block averages are descriptive when the number of blocks is small; they do not magically create independent samples. If the protocol reports uncertainty, use a method compatible with serial dependence and disclose its assumptions. Show sample counts, block boundaries, and any missing origins. Never drop a difficult window only because it reverses the aggregate sign.","Trung bình toàn cục có thể che chế độ phương pháp thất bại. Giữ sai khác từng mốc theo thời gian rồi tóm tắt theo khối định trước. Trung bình khối chỉ mô tả khi ít khối; không tự biến chúng thành mẫu độc lập. Nếu quy trình báo bất định, dùng phương pháp phù hợp phụ thuộc chuỗi và nêu giả định. Hiển thị số mẫu, ranh giới khối và mốc thiếu. Không bỏ cửa sổ khó chỉ vì nó đảo dấu tổng hợp."),B("Per-origin method-minus-baseline differences are [−2,−1,3,4], where negative favors the method. Freeze blocks [1,2] and [3,4]. Block means are (−2−1)/2=−1.5 and (3+4)/2=3.5; the overall mean is (−2−1+3+4)/4=1.0, so baseline is favored overall. Reporting only the first block would reverse the conclusion. Four origins are too few for a precise uncertainty claim, so show the vector and call the block view descriptive.","Sai khác phương pháp-trừ-đối chứng từng mốc là [−2,−1,3,4], âm nghiêng về phương pháp. Khóa khối [1,2] và [3,4]. Trung bình khối lần lượt (−2−1)/2=−1.5 và (3+4)/2=3.5; trung bình chung=(−2−1+3+4)/4=1.0 nên tổng thể nghiêng đối chứng. Chỉ báo khối đầu sẽ đảo kết luận. Bốn mốc quá ít để tuyên bố bất định chính xác; hãy trình bày vector và gọi tóm tắt khối là mô tả."),{"kind":"bars","title":B("Predeclared block means and overall mean","Trung bình khối định trước và trung bình chung"),"caption":B("Paired differences [−2,−1,3,4], negative favors method. Block means are −1.5 and 3.5; overall mean is +1.0.","Sai khác ghép cặp [−2,−1,3,4], âm nghiêng phương pháp. Trung bình khối −1.5 và 3.5; trung bình chung +1.0."),"xLabel":B("Summary","Tóm tắt"),"yLabel":B("Method minus baseline","Phương pháp trừ đối chứng"),"values":[{"label":B("Block 1","Khối 1"),"value":-1.5},{"label":B("Block 2","Khối 2"),"value":3.5},{"label":B("All origins","Mọi mốc"),"value":1}]},[B("60 min — Compute the overall signed mean and both frozen block means from the four differences.","60 phút — Tính trung bình có dấu toàn cục và hai trung bình khối đã khóa."),B("60 min — Identify how reporting only block 1 would change the sign and why that is selective reporting.","60 phút — Chỉ ra báo riêng khối 1 đổi dấu thế nào và vì sao đó là báo cáo chọn lọc."),B("60 min — Implement a chronological block summary that returns all origin values and block counts.","60 phút — Cài tóm tắt khối thời gian trả cả giá trị từng mốc và số lượng khối."),B("60 min — Write a cautious paragraph that states overall and block results without claiming precise uncertainty from four origins.","60 phút — Viết đoạn thận trọng nêu tổng và khối mà không tuyên bố bất định chính xác từ bốn mốc.")],X("w76-d4-blocks",B("Differences by origin are [2,−2,1,−1,4,−4], with blocks [1,2], [3,4], [5,6]. Compute each block mean and the overall mean. What information would be lost by publishing only the overall mean?","Sai khác theo mốc [2,−2,1,−1,4,−4], chia khối [1,2],[3,4],[5,6]. Tính trung bình từng khối và chung. Chỉ đăng trung bình chung sẽ mất gì?"),B("Each block has two entries. Keep their signs; the overall sum may cancel.","Mỗi khối có hai giá trị. Giữ dấu; tổng chung có thể triệt tiêu."),B("Block means are 0, 0, and 0; overall mean is 0. The vector shows large alternating effects (+2/−2, +1/−1, +4/−4) that the aggregate hides. With only six dependent origins, this is descriptive, not evidence of zero variability or no effect.","Trung bình khối là 0,0,0; trung bình chung=0. Vector cho thấy hiệu ứng luân phiên lớn (+2/−2,+1/−1,+4/−4) bị tổng hợp che. Chỉ sáu mốc có thể phụ thuộc nên đây là mô tả, không chứng minh biến thiên bằng không hay không có hiệu ứng."))),
 S(B("76.5 — Reproduction seeks compatible evidence","76.5 — Tái lập tìm bằng chứng tương thích"),B("A stochastic reproduction need not match the published digits exactly. Specify what was randomized, which seeds were used, what summary is compared, and an uncertainty range. Separate procedural reproducibility (same code/configuration runs) from numerical compatibility (results plausibly overlap under stated variation). If an implementation change is needed, first preserve the original attempt, then document the patch and rerun. A compatible estimate does not prove the original causal story; a mismatch is a diagnostic signal, not automatic misconduct.","Tái lập ngẫu nhiên không cần khớp từng chữ số công bố. Nêu yếu tố ngẫu nhiên, seed, tóm tắt được so và khoảng bất định. Tách khả năng chạy lại quy trình (cùng mã/cấu hình chạy được) khỏi tương thích số (kết quả có thể chồng lấp dưới biến thiên đã nêu). Nếu cần sửa triển khai, giữ lần thử cũ trước, ghi bản vá rồi chạy lại. Ước lượng tương thích không chứng minh câu chuyện nhân quả gốc; sai khác là tín hiệu chẩn đoán, không tự động là sai phạm."),B("The published toy benchmark reports mean loss 1.00 with run-to-run standard deviation 0.20 across 5 seeds. A faithful local run gives mean 1.08 and SD 0.18 across 5 predeclared seeds. Mean difference is 0.08; the scale of one SD is about 0.20. This looks numerically compatible for a small illustrative sample, but five seeds do not produce a precise interval and do not validate the paper's data or interpretation. Preserve all ten seed-level outputs and the exact configuration.","Benchmark đồ chơi công bố loss trung bình 1.00, độ lệch chuẩn giữa lần chạy 0.20 trên 5 seed. Chạy cục bộ trung thành cho trung bình 1.08, SD 0.18 trên 5 seed định trước. Chênh trung bình 0.08; độ lớn một SD khoảng 0.20. Có vẻ tương thích số trong mẫu minh họa nhỏ, nhưng 5 seed không cho khoảng chính xác và không xác nhận dữ liệu hay diễn giải bài gốc. Giữ đủ 10 đầu ra từng seed và cấu hình chính xác."),{"kind":"bars","title":B("Published and reproduced toy summaries","Tóm tắt đồ chơi công bố và tái lập"),"caption":B("Five-seed published mean loss=1.00, SD=0.20; local five-seed mean=1.08, SD=0.18. The figure shows means only; the small seed count limits precision.","Loss trung bình công bố trên 5 seed=1.00, SD=0.20; cục bộ 5 seed=1.08, SD=0.18. Hình chỉ cho trung bình; ít seed làm hạn chế độ chính xác."),"xLabel":B("Run summary","Tóm tắt lần chạy"),"yLabel":B("Mean loss","Loss trung bình"),"values":[{"label":B("Published","Công bố"),"value":1},{"label":B("Local reproduction","Tái lập cục bộ"),"value":1.08}]},[B("60 min — Define procedural reproducibility and numerical compatibility separately in the report template.","60 phút — Định nghĩa khả năng chạy lại quy trình và tương thích số riêng trong mẫu báo cáo."),B("60 min — Calculate the mean difference and express it relative to the supplied run-to-run SD without calling it a significance test.","60 phút — Tính chênh trung bình và biểu diễn tương đối với SD lần chạy đã cho, không gọi đây là kiểm định ý nghĩa."),B("60 min — Create a seed table with five published and five local outputs; make no selection by result magnitude.","60 phút — Tạo bảng seed gồm năm đầu ra công bố và năm cục bộ; không chọn theo độ lớn kết quả."),B("60 min — Write a reproduction status paragraph naming compatibility, sample-size limitation, and unverified external claim.","60 phút — Viết đoạn trạng thái tái lập nêu tương thích, giới hạn cỡ mẫu và tuyên bố bên ngoài chưa xác minh.")],X("w76-d5-compatible",B("A reference gives mean 2.0, SD 0.5 over 4 seeds. Your predeclared run gives mean 2.3, SD 0.4 over 4 seeds. Compute the mean gap and write a cautious compatibility statement; do not infer a formal significance result.","Nguồn cho trung bình 2.0, SD 0.5 trên 4 seed. Chạy định trước cho trung bình 2.3, SD 0.4 trên 4 seed. Tính chênh và viết nhận xét tương thích thận trọng; không suy ra kiểm định ý nghĩa."),B("Subtract means. Compare the gap with the reported variability, then state the limitation from only four seeds.","Trừ hai trung bình. So chênh với biến thiên đã báo, rồi nêu giới hạn chỉ bốn seed."),B("Gap=2.3−2.0=0.3, which is smaller than the reference SD 0.5. A cautious statement is that these small summaries are not obviously incompatible under the reported variability, but four seeds give imprecise evidence. This is not a significance test and does not confirm the source's data, code, or causal interpretation.","Chênh=2.3−2.0=0.3, nhỏ hơn SD nguồn 0.5. Có thể nói thận trọng rằng các tóm tắt nhỏ chưa cho thấy mâu thuẫn rõ dưới biến thiên đã nêu, nhưng bốn seed cho bằng chứng thiếu chính xác. Đây không phải kiểm định ý nghĩa và không xác nhận dữ liệu, mã hay diễn giải nhân quả của nguồn.")))
 ],{"kind":"timeline","title":B("Fit past → forecast → reveal → advance","Khớp quá khứ → dự báo → mở kết quả → tiến mốc"),"labels":["training prefix","forecast origin","revealed target","update / refit","next origin"],"caption":B("The walk-forward procedure preserves timing; overlapping targets and refitting rules must be part of the estimand.","Quy trình tiến thời gian giữ trình tự; mục tiêu chồng lấn và quy tắc khớp lại thuộc đặc tả đại lượng.")})

modules=[W71,W72,W73,W74,W75,W76]
out=ROOT/"data/lessons-71-86.json"
existing=json.loads(out.read_text(encoding="utf-8")) if out.exists() else []
modules=sorted([m for m in existing if m["week"] not in {x["week"] for x in modules}]+modules,key=lambda m:m["week"])
out.write_text(json.dumps(modules,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
print(f"Wrote {len(modules)} manual modules / {sum(len(m['sessions']) for m in modules)} sessions to {out}")
